const config = {
  "previewFeatures": [],
  "clientVersion": "7.8.0",
  "engineVersion": "3c6e192761c0362d496ed980de936e2f3cebcd3a",
  "activeProvider": "postgresql",
  "inlineSchema": "generator client {\n  provider      = \"prisma-client-js\"\n  output        = \"../src/generated/prisma\"\n  binaryTargets = [\"native\", \"linux-musl-openssl-3.0.x\"]\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ─── Utilizadores ────────────────────────────────────────────────────────────\n// Roles e sub-roles são geridas dinamicamente via RoleConfig / SubRoleConfig.\n// Os campos role e subRole em Utilizador são strings livres (chave da RoleConfig/SubRoleConfig).\n\nmodel RoleConfig {\n  id        String  @id @default(uuid())\n  chave     String  @unique // 'medico', 'enfermeiro', 'ti', etc.\n  label     String // 'Médico', 'Enfermeiro', 'TI', etc.\n  categoria String // 'clinico', 'suporte', 'gestao', 'ti'\n  ativo     Boolean @default(true)\n  ordem     Int     @default(0)\n\n  subRoles SubRoleConfig[]\n\n  @@map(\"roles_config\")\n}\n\nmodel SubRoleConfig {\n  id        String  @id @default(uuid())\n  chave     String  @unique // 'cardiologista', 'it_admin', 'generalista', etc.\n  label     String // 'Cardiologista', 'IT Admin', 'Generalista', etc.\n  roleChave String // chave da role-pai (loose FK a RoleConfig.chave)\n  ativo     Boolean @default(true)\n  ordem     Int     @default(0)\n\n  role RoleConfig @relation(fields: [roleChave], references: [chave], onDelete: Cascade)\n\n  @@map(\"subroles_config\")\n}\n\nenum Servico {\n  internamento\n  urgencia\n  bloco_operatorio\n  consultas_externas\n  farmacia\n  fisioterapia\n  transporte\n  administrativo\n}\n\nmodel Utilizador {\n  id                String    @id @default(uuid())\n  tenantId          String    @default(\"default\")\n  numeroFuncionario String    @unique\n  nome              String\n  passwordHash      String\n  mfaSecret         String?\n  mfaAtivo          Boolean   @default(false)\n  passwordExpiresAt DateTime?\n  role              String // chave de RoleConfig (ex: 'medico', 'enfermeiro', 'ti')\n  subRole           String? // chave de SubRoleConfig (ex: 'cardiologista', 'it_admin')\n  servico           Servico   @default(internamento)\n  ordemExperiencia  Int? // definida pela chefe de enfermeiros\n  equipa            String? // ex: \"A\", \"B\", \"C\"\n  ativo             Boolean   @default(true)\n  criadoEm          DateTime  @default(now())\n  atualizadoEm      DateTime  @updatedAt\n\n  // Relações existentes\n  turnosComoChefe                Turno[]                     @relation(\"ChefeTurno\")\n  horariosEntrada                HorarioEntrada[]\n  notasTurno                     NotaTurno[]\n  tarefasCriadas                 Tarefa[]                    @relation(\"TarefaCriadaPor\")\n  tarefasResponsavel             Tarefa[]                    @relation(\"TarefaResponsavel\")\n  medicacoesPrescritas           Medicacao[]                 @relation(\"MedicacaoPrescritor\")\n  registosMedicacao              RegistoMedicacao[]\n  doentesAdmitidos               Doente[]                    @relation(\"DoenteAdmissao\")\n  escalas                        Escala[]\n  atribuicoesEnfermeiro          AtribuicaoDoente[]\n  horariosTurnoProfissional      HorarioTurnoProfissional[]\n  atribuicoesComoUtilizador      AtribuicaoHorarioTurno[]    @relation(\"AtribuicaoUtilizador\")\n  atribuicoesFeitas              AtribuicaoHorarioTurno[]    @relation(\"AtribuicaoAtribuidoPor\")\n  trocasSolicitadas              PedidoTrocaTurno[]          @relation(\"TrocaSolicitante\")\n  trocasRecebidas                PedidoTrocaTurno[]          @relation(\"TrocaDestinatario\")\n  trocasAprovadas                PedidoTrocaTurno[]          @relation(\"TrocaAprovadoPor\")\n  auditLogs                      AuditLog[]\n  sinaisVitaisRegistados         SinalVital[]                @relation(\"SinaisVitaisRegistados\")\n  dispositivosTokens             DispositivoToken[]\n  notificacoesInApp              NotificacaoInApp[]\n  avaliacoesRisco                AvaliacaoRisco[]\n  sumariosAlta                   SumarioAlta[]\n  // Novos — Fase 7\n  notasClinciasAutor             NotaClinica[]\n  escalasClinicasRegistadas      EscalaClinica[]\n  // Novos — Fase 5\n  examesSolicitados              Exame[]                     @relation(\"ExameSolicitadoPor\")\n  episodiosTriados               EpisodioUrgencia[]          @relation(\"EpisodioTriador\")\n  episodiosMedico                EpisodioUrgencia[]          @relation(\"EpisodioMedico\")\n  cirurgiasComoCircurgiao        CirurgiaProgramada[]        @relation(\"CirurgiaCircurgiao\")\n  cirurgiasComoAnestesista       CirurgiaProgramada[]        @relation(\"CirurgiaAnestesista\")\n  consultas                      Consulta[]\n  stockPedidosSolicitados        PedidoFarmacia[]            @relation(\"PedidoSolicitante\")\n  stockPedidosProcessados        PedidoFarmacia[]            @relation(\"PedidoProcessador\")\n  stockPedidosAprovados          PedidoFarmacia[]            @relation(\"PedidoAprovador\")\n  planosReabilitacao             PlanoReabilitacao[]\n  sessoesFisioterapia            SessaoFisioterapia[]\n  pedidosInternosSolicitados     PedidoInterno[]             @relation(\"PedidoInternoSolicitante\")\n  pedidosInternosExecutados      PedidoInterno[]             @relation(\"PedidoInternoExecutor\")\n  anunciosPublicados             Anuncio[]\n  mensagensEnviadas              MensagemInterna[]           @relation(\"MensagemRemetente\")\n  mensagensRecebidas             MensagemInterna[]           @relation(\"MensagemDestinatario\")\n  // Novos — Fase 8A\n  interconsultasRequisitadas     Interconsulta[]             @relation(\"InterconsultaRequisitante\")\n  interconsultasRespondidas      Interconsulta[]             @relation(\"InterconsultaResposta\")\n  dispositivosInseridos          DispositivoInvasivo[]       @relation(\"DispositivoInserido\")\n  // Novos — Fase 8B\n  medicacoesValidadas            Medicacao[]                 @relation(\"MedicacaoValidador\")\n  // Novos — Fase 8B WHO Checklist\n  checklistsSignIn               ChecklistCirurgia[]         @relation(\"ChecklistSignIn\")\n  checklistsTimeOut              ChecklistCirurgia[]         @relation(\"ChecklistTimeOut\")\n  checklistsSignOut              ChecklistCirurgia[]         @relation(\"ChecklistSignOut\")\n  // Novos — Fase 8C Sala de Espera\n  checkinsRececionados           CheckinSalaEspera[]         @relation(\"CheckinRececionista\")\n  checkinsAtendidos              CheckinSalaEspera[]         @relation(\"CheckinMedico\")\n  refreshTokens                  RefreshToken[]\n  incidentesCriados              IncidenteTI[]               @relation(\"IncidentesCriados\")\n  incidentesAtribuidos           IncidenteTI[]               @relation(\"IncidentesAtribuidos\")\n  pedidosTICriados               PedidoTI[]                  @relation(\"PedidosTICriados\")\n  pedidosTIAtribuidos            PedidoTI[]                  @relation(\"PedidosTIAtribuidos\")\n  ficheirosPessoaisAtualizados   FicheiroPessoalDoente[]\n  episodiosFaturacaoCriados      EpisodioFaturacao[]\n  pagamentosRegistados           Pagamento[]\n  agendas                        AgendaMedico[]              @relation(\"AgendaMedico\")\n  problemasRegistados            ProblemaClinico[]           @relation(\"ProblemaRegistado\")\n  manutencoesReportadas          Manutencao[]                @relation(\"ManutencaoReportada\")\n  manutencoesTecnico             Manutencao[]                @relation(\"ManutencaoTecnico\")\n  alertasAcusados                AlertaClinico[]             @relation(\"AlertaAcusador\")\n  // RH\n  ausencias                      Ausencia[]                  @relation(\"AusenciaUtilizador\")\n  ausenciasAprovadas             Ausencia[]                  @relation(\"AusenciaAprovador\")\n  formacoes                      FormacaoUtilizador[]        @relation(\"FormacaoUtilizador\")\n  eventosAdversosRegistados      EventoAdverso[]             @relation(\"EventoAdversoRegistado\")\n  // Especialidades\n  sessoesEspecialidade           SessaoEspecialidade[]       @relation(\"SessaoEspecialidadeProfissional\")\n  // RH expandido\n  avaliacoesComoAvaliado         AvaliacaoDesempenho[]       @relation(\"AvaliacaoAvaliado\")\n  avaliacoesComoAvaliador        AvaliacaoDesempenho[]       @relation(\"AvaliacaoAvaliador\")\n  dadosContratuais               DadosContratuais?\n  // Chefe directo (hierarquia para aprovação de férias)\n  chefeId                        String?\n  chefe                          Utilizador?                 @relation(\"ChefeSubordinado\", fields: [chefeId], references: [id], onDelete: SetNull)\n  subordinados                   Utilizador[]                @relation(\"ChefeSubordinado\")\n  // Inventário expandido\n  ajustesStock                   AjusteStock[]               @relation(\"AjustesFeitos\")\n  transferenciasSolicitadas      TransferenciaStock[]        @relation(\"TransfSolicitadas\")\n  transferenciasConfirmadas      TransferenciaStock[]        @relation(\"TransfConfirmadas\")\n  encomendasRecebidas            EncomendaFornecedor[]       @relation(\"EncomendasRecebidas\")\n  presencaOnline                 PresencaOnline?\n  registosCheckin                RegistoCheckin[]\n  consentimentosCriados          ConsentimentoInformado[]    @relation(\"ConsentimentoCriador\")\n  consentimentosTestemunha       ConsentimentoInformado[]    @relation(\"ConsentimentoTestemunha\")\n  breakGlassUsados               BreakGlassAccess[]\n  protocolosAtivados             ProtocoloClinico[]\n  itensProtocoloConcluidos       ItemProtocolo[]\n  prescricoesDietaCriadas        PrescricaoDieta[]\n  medicacoesAssinadas            Medicacao[]                 @relation(\"MedicacaoAssinatura\")\n  notasAssinadas                 NotaClinica[]               @relation(\"NotaAssinatura\")\n  culturasRegistadas             CulturaMicrobiologica[]\n  surtosRegistados               SurtoIACS[]\n  notasIncidentesTI              NotaIncidenteTI[]           @relation(\"NotasIncidentesTI\")\n  checklistsConformidade         ConformidadeChecklistItem[] @relation(\"ChecklistAtualizador\")\n  // Trocas de folga\n  trocasFolgaSolicitadas         TrocaFolga[]                @relation(\"TrocaFolgaSolicitante\")\n  trocasFolgaRecebidas           TrocaFolga[]                @relation(\"TrocaFolgaDestinatario\")\n  trocasFolgaAprovadas           TrocaFolga[]                @relation(\"TrocaFolgaAprovador\")\n  balancosHidricosRegistados     BalancoHidrico[]            @relation(\"BalancoHidricoRegistadoPor\")\n  feridasRegistadas              AvaliacaoFerida[]           @relation(\"FeridasRegistadoPor\")\n  atualizacoesTransporte         AtualizacaoTransporte[]     @relation(\"AtualizacaoTransporteRegistadoPor\")\n  episodiosEspecialidadeActivada EpisodioUrgencia[]          @relation(\"EpisodioEspecialidadeActivadaPor\")\n  sinalizacoesCriadas            SinalizacaoPreocupante[]    @relation(\"SinalizacoesCriadas\")\n  sinalizacoesResolvidas         SinalizacaoPreocupante[]    @relation(\"SinalizacoesResolvidas\")\n  relatoriosPassagemCriados      RelatorioPassagemTurno[]    @relation(\"RelatorioPassagemCriado\")\n  relatoriosPassagemConfirmados  RelatorioPassagemTurno[]    @relation(\"RelatorioPassagemConfirmado\")\n  reconciliacoesCriadas          ReconciliacaoMedicacao[]    @relation(\"ReconciliacoesCriadas\")\n  reconciliacoesAprovadas        ReconciliacaoMedicacao[]    @relation(\"ReconciliacoesAprovadas\")\n  acessosFamiliaresCriados       AcessoFamiliar[]            @relation(\"AcessoFamiliarCriado\")\n  resultadosAnaliseRegistados    ResultadoAnalise[]          @relation(\"ResultadosAnaliseRegisto\")\n  documentosSaudeRegistados      DocumentoSaude[]            @relation(\"DocumentosSaudeRegisto\")\n  documentosSaudeAssinados       DocumentoSaude[]            @relation(\"DocumentoSaudeAssinatura\")\n  aiDecisoes                     AiDecisao[]                 @relation(\"AiDecisoes\")\n  fotosFeridas                   FotoFerida[]                @relation(\"FotosFeridasCriadas\")\n  portaisCriados                 PortalDoente[]              @relation(\"PortalDoentesCriados\")\n  dashboardConfig                DashboardConfig?\n  followUpsResponsavel           FollowUpAgendado[]\n  outcomesRegistados             OutcomeClinico[]            @relation(\"OutcomesRegistados\")\n  webhooksCriados                Webhook[]                   @relation(\"WebhooksCriados\")\n  cohortsCriadas                 CohortDefinition[]          @relation(\"CohortsCriadas\")\n  transExternasSolicitadas       TransferenciaExterna[]      @relation(\"TransferenciasSolicitadas\")\n  transExternasAceites           TransferenciaExterna[]      @relation(\"TransferenciasAceites\")\n  regrasCliniasCriadas           RegraClinica[]              @relation(\"RegrasCliniasCriadas\")\n  webAuthnCredentials            WebAuthnCredential[]\n  transfusoesPrescritas          PedidoTransfusao[]          @relation(\"TransfusoesPrescritas\")\n  transfusoesAdministradas       RegistoTransfusao[]         @relation(\"TransfusoesAdministradas\")\n  reacoesTransfusionaisRegisto   ReacaoTransfusional[]       @relation(\"ReacoesTransfusRegisto\")\n\n  @@index([tenantId, role, ativo])\n  @@index([role, ativo])\n  @@index([servico])\n  @@map(\"utilizadores\")\n}\n\n// ─── Camas ───────────────────────────────────────────────────────────────────\n\nenum EstadoCama {\n  livre\n  ocupada\n  em_limpeza\n  reservada\n}\n\nmodel Cama {\n  id       String     @id @default(uuid())\n  tenantId String     @default(\"default\")\n  numero   String     @unique\n  quarto   String\n  estado   EstadoCama @default(livre)\n  servico  String?\n  piso     Int?\n\n  doente Doente?\n\n  @@index([quarto, estado])\n  @@index([servico, estado])\n  @@map(\"camas\")\n}\n\n// ─── Doentes ─────────────────────────────────────────────────────────────────\n\nenum EstadoDoente {\n  estavel\n  grave\n  critico\n  alta_prevista\n}\n\nmodel Doente {\n  id                   String       @id @default(uuid())\n  tenantId             String       @default(\"default\")\n  nome                 String\n  dataNascimento       DateTime?\n  numeroProcesso       String       @unique\n  estado               EstadoDoente @default(estavel)\n  diagnosticoPrincipal String?\n  icd10Code            String?\n  grupoSanguineo       String? // grupo ABO/Rh do doente (ex.: 'A+', 'O-') — do type & screen\n  estadoRegisto        String       @default(\"pendente_cama\") // 'pendente_cama' | 'internado' | 'ambulatorio'\n  tipoVisita           String? // 'consulta' | 'exame' | 'urgencia' | 'farmacia' | 'internamento' | 'outro'\n  dataAdmissao         DateTime     @default(now())\n  dataAltaPrevista     DateTime?\n  dataAlta             DateTime?\n  ativo                Boolean      @default(true)\n  emIsolamento         Boolean      @default(false)\n  motivoIsolamento     String?\n  deletedAt            DateTime?\n  fotoUrl              String?\n\n  camaId String? @unique\n  cama   Cama?   @relation(fields: [camaId], references: [id], onDelete: SetNull)\n\n  administrativoAdmissaoId String?\n  administrativo           Utilizador? @relation(\"DoenteAdmissao\", fields: [administrativoAdmissaoId], references: [id], onDelete: SetNull)\n\n  // Relações existentes\n  atribuicoes             AtribuicaoDoente[]\n  atribuicoesHorario      AtribuicaoHorarioTurno[]\n  tarefas                 Tarefa[]\n  medicacoes              Medicacao[]\n  registosMedicacao       RegistoMedicacao[]\n  notasTurno              NotaTurno[]\n  passagensTurno          PassagemTurno[]\n  sinaisVitais            SinalVital[]\n  alergias                Alergia[]\n  contactosEmergencia     ContactoEmergencia[]\n  alertasClinicos         AlertaClinico[]\n  avaliacoesRisco         AvaliacaoRisco[]\n  sumarioAlta             SumarioAlta?\n  // Novos — Fase 7\n  notasClincias           NotaClinica[]\n  escalasClinicas         EscalaClinica[]\n  // Novos — Fase 5\n  exames                  Exame[]\n  episodiosUrgencia       EpisodioUrgencia[]\n  cirurgias               CirurgiaProgramada[]\n  consultas               Consulta[]\n  planosReabilitacao      PlanoReabilitacao[]\n  sessoesFisioterapia     SessaoFisioterapia[]\n  sessoesEspecialidade    SessaoEspecialidade[]\n  pedidosInternos         PedidoInterno[]\n  // Novos — Fase 8A\n  interconsultas          Interconsulta[]\n  dispositivosInvasivos   DispositivoInvasivo[]\n  // Dados administrativos (acesso restrito a role 'administrativo')\n  ficheiroPessoal         FicheiroPessoalDoente?\n  episodiosFaturacao      EpisodioFaturacao[]\n  problemas               ProblemaClinico[]\n  eventosAdversos         EventoAdverso[]          @relation(\"EventosAdversosDoente\")\n  consentimentos          ConsentimentoInformado[]\n  breakGlassAcessos       BreakGlassAccess[]\n  protocolosClinicos      ProtocoloClinico[]\n  prescricoesDieta        PrescricaoDieta[]\n  culturasMicrobiologicas CulturaMicrobiologica[]\n  balancosHidricos        BalancoHidrico[]\n  feridas                 AvaliacaoFerida[]\n  sinalizacoes            SinalizacaoPreocupante[]\n  alertasSepsis           AlertaSepsis[]\n  baseline                BaselineDoente?\n  planoAlta               PlanoAlta?\n  reconciliacoesMedicacao ReconciliacaoMedicacao[]\n  acessosFamiliares       AcessoFamiliar[]\n  resultadosAnalise       ResultadoAnalise[]\n  documentosSaude         DocumentoSaude[]\n  identificadoresExternos IdentificadorExterno[]\n  portalDoente            PortalDoente?\n  registosPro             RegistoPRO[]\n  transferenciasExternas  TransferenciaExterna[]\n  stewardshipAntibioticos StewardshipAntibiotico[]\n  followUps               FollowUpAgendado[]\n  outcomesClinicos        OutcomeClinico[]\n  pedidosTransfusao       PedidoTransfusao[]\n  registosTransfusao      RegistoTransfusao[]\n  reacoesTransfusionais   ReacaoTransfusional[]\n  gravidezes              Gravidez[]\n  planosQuimioterapia     PlanoQuimioterapia[]\n  sessoesDialise          SessaoDialise[]\n\n  @@index([tenantId, estado])\n  @@index([ativo])\n  @@index([estado])\n  @@index([dataAdmissao])\n  @@index([deletedAt])\n  @@map(\"doentes\")\n}\n\n// ─── Turnos e Horários ────────────────────────────────────────────────────────\n\nenum TipoTurno {\n  manha\n  tarde\n  noite\n}\n\nmodel Turno {\n  id         String    @id @default(uuid())\n  tipo       TipoTurno\n  dataInicio DateTime\n  dataFim    DateTime\n\n  chefeTurnoId String\n  chefeTurno   Utilizador @relation(\"ChefeTurno\", fields: [chefeTurnoId], references: [id], onDelete: Restrict)\n\n  atribuicoes            AtribuicaoDoente[]\n  horariosEntrada        HorarioEntrada[]\n  notasTurno             NotaTurno[]\n  tarefas                Tarefa[]\n  passagensTurnoAnterior PassagemTurno[]    @relation(\"PassagemTurnoAnterior\")\n  passagensTurnoAtual    PassagemTurno[]    @relation(\"PassagemTurnoAtual\")\n\n  @@index([chefeTurnoId])\n  @@index([dataInicio])\n  @@index([dataInicio, dataFim, tipo])\n  @@map(\"turnos\")\n}\n\nmodel AtribuicaoDoente {\n  id           String @id @default(uuid())\n  doenteId     String\n  enfermeiroId String\n  turnoId      String\n\n  doente     Doente     @relation(fields: [doenteId], references: [id], onDelete: Cascade)\n  enfermeiro Utilizador @relation(fields: [enfermeiroId], references: [id], onDelete: Cascade)\n  turno      Turno      @relation(fields: [turnoId], references: [id], onDelete: Cascade)\n\n  @@unique([doenteId, enfermeiroId, turnoId])\n  @@map(\"atribuicoes_doente\")\n}\n\nmodel HorarioEntrada {\n  id                 String   @id @default(uuid())\n  turnoId            String\n  utilizadorId       String\n  checkInEm          DateTime @default(now())\n  passagemTurnoVista Boolean  @default(false)\n\n  turno      Turno      @relation(fields: [turnoId], references: [id], onDelete: Cascade)\n  utilizador Utilizador @relation(fields: [utilizadorId], references: [id], onDelete: Cascade)\n\n  @@unique([turnoId, utilizadorId])\n  @@map(\"horarios_entrada\")\n}\n\nmodel PassagemTurno {\n  id              String @id @default(uuid())\n  turnoAnteriorId String\n  turnoAtualId    String\n  doenteId        String\n\n  // Desafio de presença em tempo real\n  estadoDesafio     String    @default(\"pendente\") // pendente | aceite | expirado\n  desafioEnviadoEm  DateTime?\n  desafioAceitoEm   DateTime?\n  desafioExpiradoEm DateTime?\n\n  turnoAnterior Turno  @relation(\"PassagemTurnoAnterior\", fields: [turnoAnteriorId], references: [id], onDelete: Cascade)\n  turnoAtual    Turno  @relation(\"PassagemTurnoAtual\", fields: [turnoAtualId], references: [id], onDelete: Cascade)\n  doente        Doente @relation(fields: [doenteId], references: [id], onDelete: Cascade)\n\n  @@index([estadoDesafio])\n  @@map(\"passagens_turno\")\n}\n\nmodel PresencaOnline {\n  id           String     @id @default(uuid())\n  utilizadorId String     @unique\n  utilizador   Utilizador @relation(fields: [utilizadorId], references: [id], onDelete: Cascade)\n  socketId     String\n  ligadoEm     DateTime   @default(now())\n  ultimoPing   DateTime   @default(now())\n\n  @@map(\"presenca_online\")\n}\n\nmodel RegistoCheckin {\n  id                String     @id @default(uuid())\n  utilizadorId      String\n  utilizador        Utilizador @relation(fields: [utilizadorId], references: [id], onDelete: Cascade)\n  turnoId           String?\n  lat               Float?\n  lon               Float?\n  distanciaHospital Float?\n  dentroGeofence    Boolean    @default(true)\n  ip                String?\n  criadoEm          DateTime   @default(now())\n\n  @@index([utilizadorId, criadoEm])\n  @@map(\"registos_checkin\")\n}\n\n// ─── Notas Clínicas SOAP ─────────────────────────────────────────────────────\n\nmodel NotaClinica {\n  id            String      @id @default(uuid())\n  doenteId      String\n  doente        Doente      @relation(fields: [doenteId], references: [id], onDelete: Cascade)\n  autorId       String\n  autor         Utilizador  @relation(fields: [autorId], references: [id], onDelete: Cascade)\n  subjetivo     String\n  objetivo      String\n  avaliacao     String\n  plano         String\n  criadaEm      DateTime    @default(now())\n  editadaEm     DateTime?\n  deletedAt     DateTime?\n  assinadaEm    DateTime?\n  assinadaPorId String?\n  assinadaPor   Utilizador? @relation(\"NotaAssinatura\", fields: [assinadaPorId], references: [id], onDelete: SetNull)\n\n  @@index([doenteId, criadaEm])\n  @@index([deletedAt])\n  @@index([doenteId, deletedAt])\n  @@map(\"notas_clinicas\")\n}\n\n// ─── Escalas Clínicas Especializadas ─────────────────────────────────────────\n\nenum TipoEscalaClinica {\n  RASS\n  CPOT\n  SOFA\n  CTG\n  Apgar\n  PEWS\n  FLACC\n  Barthel\n  FIM\n  MRC\n  FOIS\n  NRS2002\n  PHQ9\n  GAD7\n  Glasgow\n}\n\nmodel EscalaClinica {\n  id             String            @id @default(uuid())\n  doenteId       String\n  doente         Doente            @relation(fields: [doenteId], references: [id], onDelete: Cascade)\n  registadoPorId String\n  registadoPor   Utilizador        @relation(fields: [registadoPorId], references: [id], onDelete: Cascade)\n  tipo           TipoEscalaClinica\n  valores        Json\n  pontuacao      Int?\n  classificacao  String?\n  observacoes    String?\n  registadaEm    DateTime          @default(now())\n\n  @@index([doenteId, tipo])\n  @@map(\"escalas_clinicas\")\n}\n\n// ─── Notas de Turno ──────────────────────────────────────────────────────────\n\nmodel NotaTurno {\n  id       String   @id @default(uuid())\n  texto    String\n  criadaEm DateTime @default(now())\n\n  turnoId  String?\n  doenteId String\n  autorId  String\n\n  turno  Turno?     @relation(fields: [turnoId], references: [id], onDelete: SetNull)\n  doente Doente     @relation(fields: [doenteId], references: [id], onDelete: Cascade)\n  autor  Utilizador @relation(fields: [autorId], references: [id], onDelete: Cascade)\n\n  @@map(\"notas_turno\")\n}\n\n// ─── Tarefas ─────────────────────────────────────────────────────────────────\n\nenum TipoTarefa {\n  clinica\n  logistica\n}\n\nenum PrioridadeTarefa {\n  baixa\n  media\n  alta\n  urgente\n}\n\nenum EstadoTarefa {\n  pendente\n  em_progresso\n  concluida\n  cancelada\n}\n\nmodel Tarefa {\n  id               String           @id @default(uuid())\n  descricao        String\n  tipo             TipoTarefa\n  prioridade       PrioridadeTarefa @default(media)\n  estado           EstadoTarefa     @default(pendente)\n  prazo            DateTime?\n  transitouDeTurno Boolean          @default(false)\n  criadaEm         DateTime         @default(now())\n  concluidaEm      DateTime?\n\n  doenteId         String\n  responsavelId    String?\n  grupoResponsavel String?\n  criadoPorId      String\n  turnoId          String?\n\n  doente      Doente      @relation(fields: [doenteId], references: [id], onDelete: Cascade)\n  responsavel Utilizador? @relation(\"TarefaResponsavel\", fields: [responsavelId], references: [id], onDelete: SetNull)\n  criadoPor   Utilizador  @relation(\"TarefaCriadaPor\", fields: [criadoPorId], references: [id], onDelete: Cascade)\n  turno       Turno?      @relation(fields: [turnoId], references: [id], onDelete: SetNull)\n\n  @@index([doenteId, estado])\n  @@index([responsavelId, estado])\n  @@map(\"tarefas\")\n}\n\n// ─── Medicação ───────────────────────────────────────────────────────────────\n\nmodel Medicacao {\n  id          String    @id @default(uuid())\n  tenantId    String    @default(\"default\")\n  nome        String\n  dose        String\n  via         String\n  frequencia  String\n  ativo       Boolean   @default(true)\n  iniciadoEm  DateTime  @default(now())\n  terminadoEm DateTime?\n  deletedAt   DateTime?\n\n  doenteId       String\n  prescritoPorId String\n\n  estadoValidacao String? // pendente | aprovada | rejeitada\n  validadoPorId   String?\n  validadaEm      DateTime?\n  motivoRejeicao  String?\n  assinadoEm      DateTime?\n  assinadoPorId   String?\n\n  doente       Doente                  @relation(fields: [doenteId], references: [id], onDelete: Cascade)\n  prescritoPor Utilizador              @relation(\"MedicacaoPrescritor\", fields: [prescritoPorId], references: [id], onDelete: Cascade)\n  validadoPor  Utilizador?             @relation(\"MedicacaoValidador\", fields: [validadoPorId], references: [id], onDelete: SetNull)\n  assinadoPor  Utilizador?             @relation(\"MedicacaoAssinatura\", fields: [assinadoPorId], references: [id], onDelete: SetNull)\n  registos     RegistoMedicacao[]\n  stewardship  StewardshipAntibiotico?\n\n  @@index([doenteId, ativo])\n  @@index([doenteId, ativo, iniciadoEm])\n  @@index([estadoValidacao])\n  @@index([deletedAt])\n  @@index([doenteId, deletedAt])\n  @@map(\"medicacoes\")\n}\n\nmodel StewardshipAntibiotico {\n  id            String    @id @default(uuid())\n  doenteId      String\n  medicacaoId   String    @unique\n  diasTerapia   Int       @default(0)\n  categoria     String // 'broad_spectrum' | 'narrow' | 'antifungal'\n  alertaEmitido Boolean   @default(false)\n  sugestaoIA    String?   @db.Text\n  aprovadoPor   String?\n  aprovadoEm    DateTime?\n  criadoEm      DateTime  @default(now())\n\n  doente    Doente    @relation(fields: [doenteId], references: [id], onDelete: Cascade)\n  medicacao Medicacao @relation(fields: [medicacaoId], references: [id], onDelete: Cascade)\n\n  @@index([doenteId, alertaEmitido])\n  @@map(\"stewardship_antibiotico\")\n}\n\nmodel RegistoMedicacao {\n  id                 String    @id @default(uuid())\n  administradoEm     DateTime  @default(now())\n  observacoes        String?\n  verificacao5Certas Boolean   @default(false)\n  naoAdministrada    Boolean   @default(false)\n  motivoNaoAdmin     String?\n  deletedAt          DateTime?\n\n  medicacaoId       String\n  doenteId          String\n  administradoPorId String\n\n  medicacao       Medicacao  @relation(fields: [medicacaoId], references: [id], onDelete: Cascade)\n  doente          Doente     @relation(fields: [doenteId], references: [id], onDelete: Cascade)\n  administradoPor Utilizador @relation(fields: [administradoPorId], references: [id], onDelete: Cascade)\n\n  @@index([medicacaoId])\n  @@index([doenteId, administradoEm])\n  @@index([deletedAt])\n  @@index([doenteId, deletedAt])\n  @@map(\"registos_medicacao\")\n}\n\n// ─── Escalas ─────────────────────────────────────────────────────────────────\n\nmodel Escala {\n  id          String   @id @default(uuid())\n  mes         Int\n  ano         Int\n  criadaEm    DateTime @default(now())\n  criadaPorId String\n\n  criadaPor Utilizador     @relation(fields: [criadaPorId], references: [id], onDelete: Cascade)\n  turnos    HorarioTurno[]\n\n  @@unique([mes, ano])\n  @@map(\"escalas\")\n}\n\nmodel HorarioTurno {\n  id      String    @id @default(uuid())\n  tipo    TipoTurno\n  data    DateTime\n  escalId String\n\n  escala        Escala                     @relation(fields: [escalId], references: [id], onDelete: Cascade)\n  profissionais HorarioTurnoProfissional[]\n  atribuicoes   AtribuicaoHorarioTurno[]\n  trocas        PedidoTrocaTurno[]         @relation(\"TrocaTurno\")\n\n  @@map(\"horarios_turno\")\n}\n\nmodel HorarioTurnoProfissional {\n  horarioTurnoId String\n  utilizadorId   String\n\n  horarioTurno HorarioTurno @relation(fields: [horarioTurnoId], references: [id], onDelete: Cascade)\n  utilizador   Utilizador   @relation(fields: [utilizadorId], references: [id], onDelete: Cascade)\n\n  @@id([horarioTurnoId, utilizadorId])\n  @@map(\"horarios_turno_profissionais\")\n}\n\nenum EstadoPedidoTroca {\n  pendente_destinatario\n  pendente_chefe\n  aprovado\n  rejeitado\n}\n\nmodel PedidoTrocaTurno {\n  id           String            @id @default(uuid())\n  estado       EstadoPedidoTroca @default(pendente_destinatario)\n  criadoEm     DateTime          @default(now())\n  respondidoEm DateTime?\n\n  solicitanteId  String\n  turnoId        String\n  destinatarioId String\n  aprovadoPorId  String?\n\n  solicitante  Utilizador   @relation(\"TrocaSolicitante\", fields: [solicitanteId], references: [id], onDelete: Cascade)\n  destinatario Utilizador   @relation(\"TrocaDestinatario\", fields: [destinatarioId], references: [id], onDelete: Cascade)\n  turno        HorarioTurno @relation(\"TrocaTurno\", fields: [turnoId], references: [id], onDelete: Cascade)\n  aprovadoPor  Utilizador?  @relation(\"TrocaAprovadoPor\", fields: [aprovadoPorId], references: [id], onDelete: SetNull)\n\n  @@map(\"pedidos_troca_turno\")\n}\n\nmodel AtribuicaoHorarioTurno {\n  id             String @id @default(uuid())\n  horarioTurnoId String\n  doenteId       String\n  utilizadorId   String\n  atribuidoPorId String\n\n  horarioTurno HorarioTurno @relation(fields: [horarioTurnoId], references: [id], onDelete: Cascade)\n  doente       Doente       @relation(fields: [doenteId], references: [id], onDelete: Cascade)\n  utilizador   Utilizador   @relation(\"AtribuicaoUtilizador\", fields: [utilizadorId], references: [id], onDelete: Cascade)\n  atribuidoPor Utilizador   @relation(\"AtribuicaoAtribuidoPor\", fields: [atribuidoPorId], references: [id], onDelete: Cascade)\n\n  @@unique([horarioTurnoId, doenteId, utilizadorId])\n  @@index([utilizadorId, horarioTurnoId])\n  @@map(\"atribuicoes_horario_turno\")\n}\n\n// ─── Sinais Vitais ────────────────────────────────────────────────────────────\n\nmodel SinalVital {\n  id             String     @id @default(uuid())\n  doenteId       String\n  doente         Doente     @relation(fields: [doenteId], references: [id], onDelete: Cascade)\n  registadoPorId String\n  registadoPor   Utilizador @relation(\"SinaisVitaisRegistados\", fields: [registadoPorId], references: [id], onDelete: Cascade)\n  data           DateTime   @default(now())\n\n  pressaoSistolica       Int?\n  pressaoDiastolica      Int?\n  pulso                  Int?\n  temperatura            Float?\n  saturacaoO2            Int?\n  frequenciaRespiratoria Int?\n  peso                   Float?\n  notas                  String?\n  avpu                   String? // A=Alert V=Voice P=Pain U=Unresponsive (NEWS2)\n  o2Suplementar          Boolean? // parâmetro NEWS2 Scale 2\n  news2                  Int? // score NEWS2 calculado automaticamente (adulto)\n  pews                   Int? // score PEWS calculado automaticamente (pediátrico, por faixa etária)\n  glasgow                Int? // Glasgow Coma Scale 3-15 (para SOFA SNC)\n  pamMedia               Float? // Pressão Arterial Média mmHg (para SOFA cardiovascular)\n  vasopressores          Boolean? // em suporte vasopressor (para SOFA cardiovascular)\n  origem                 String?  @default(\"manual\") // 'manual' | 'monitor' (proveniência do registo)\n\n  @@index([doenteId, data])\n  @@map(\"sinais_vitais\")\n}\n\n// ─── Monitorização contínua (dispositivos de cabeceira / wearables) ──────────\n// Um dispositivo autentica-se por API-key própria (não JWT) e injeta vitais que\n// passam pela MESMA pipeline (NEWS2 + watchdog de sépsis + alertas) do registo manual.\nmodel DispositivoMonitor {\n  id            String    @id @default(uuid())\n  nome          String\n  localizacao   String?\n  apiKeyHash    String // hash (bcrypt) da chave do dispositivo\n  responsavelId String // utilizador que fica como registadoPor dos vitais ingeridos\n  doenteId      String? // opcional: dispositivo ligado a um doente/cama\n  ativo         Boolean   @default(true)\n  ultimaLeitura DateTime?\n  criadaEm      DateTime  @default(now())\n\n  @@index([ativo])\n  @@map(\"dispositivos_monitor\")\n}\n\n// ─── Balanço Hídrico ──────────────────────────────────────────────────────────\n\nmodel BalancoHidrico {\n  id             String   @id @default(uuid())\n  doenteId       String\n  registadoPorId String\n  data           DateTime @default(now())\n  tipo           String // 'entrada' | 'saida'\n  categoria      String // entrada: 'soro_iv'|'oral'|'enteral'|'outro'\n  // saida:   'urina'|'dreno'|'vomito'|'fezes'|'aspiracao'|'outro'\n  quantidade     Int // mL\n  descricao      String?\n\n  doente       Doente     @relation(fields: [doenteId], references: [id], onDelete: Cascade)\n  registadoPor Utilizador @relation(\"BalancoHidricoRegistadoPor\", fields: [registadoPorId], references: [id], onDelete: Cascade)\n\n  @@index([doenteId, data])\n  @@map(\"balancos_hidricos\")\n}\n\n// ─── Feridas e Curativos ──────────────────────────────────────────────────────\n\nmodel AvaliacaoFerida {\n  id             String    @id @default(uuid())\n  doenteId       String\n  registadoPorId String\n  criadaEm       DateTime  @default(now())\n  updatedAt      DateTime  @updatedAt\n  deletedAt      DateTime?\n\n  tipo               String // 'ulcera_pressao'|'ulcera_venosa'|'ulcera_arterial'|'cirurgica'|'traumatica'|'queimadura'|'outra'\n  localizacao        String @db.VarChar(300)\n  estadoCicatrizacao String // 'fase_inflamacao'|'fase_proliferacao'|'fase_maturacao'|'cronificada'\n\n  comprimento  Float?\n  largura      Float?\n  profundidade Float?\n\n  leito          String? // 'granulacao'|'fibrina'|'necrose_humida'|'necrose_seca'|'epitelizacao'|'misto'\n  exsudadoVolume String? // 'nenhum'|'escasso'|'moderado'|'abundante'\n  exsudadoTipo   String? // 'seroso'|'sero_sanguinolento'|'sanguinolento'|'purulento'\n  periferia      String? // 'normal'|'eritema'|'edema'|'macerada'|'seca'|'callosa'\n  dor            Int? // 0-10 NRS\n  odor           Boolean @default(false)\n\n  pensoAplicado String?   @db.VarChar(200)\n  proximaTroca  DateTime?\n  notas         String?   @db.VarChar(2000)\n\n  doente       Doente       @relation(fields: [doenteId], references: [id], onDelete: Cascade)\n  registadoPor Utilizador   @relation(\"FeridasRegistadoPor\", fields: [registadoPorId], references: [id], onDelete: Cascade)\n  fotos        FotoFerida[]\n\n  @@index([doenteId, criadaEm])\n  @@map(\"avaliacoes_feridas\")\n}\n\n// ─── Sangue / Transfusão ─────────────────────────────────────────────────────\n// Segue o estilo dos modelos clínicos: valores enum-like como String com comentário.\n// Compatibilidade ABO/Rh é validada em serviço (dupla-verificação, análoga aos \"5 certos\").\n\nmodel BolsaSangue {\n  id              String    @id @default(uuid())\n  tenantId        String    @default(\"default\")\n  numeroUnidade   String    @unique // código da bolsa (etiqueta do banco de sangue / ISBT 128)\n  componente      String // 'concentrado_eritrocitos'|'plasma_fresco_congelado'|'concentrado_plaquetas'|'crioprecipitado'|'sangue_total'\n  grupoABO        String // 'A'|'B'|'AB'|'O'\n  rhD             String // 'positivo'|'negativo'\n  volumeMl        Int?\n  dataColheita    DateTime?\n  dataValidade    DateTime\n  estado          String    @default(\"disponivel\") // 'disponivel'|'reservada'|'transfundida'|'expirada'|'descartada'\n  reservadaParaId String?\n  criadaEm        DateTime  @default(now())\n  updatedAt       DateTime  @updatedAt\n\n  reservadaPara     PedidoTransfusao?  @relation(fields: [reservadaParaId], references: [id], onDelete: SetNull)\n  registoTransfusao RegistoTransfusao?\n\n  @@index([tenantId, estado])\n  @@index([componente, grupoABO, rhD, estado])\n  @@index([dataValidade])\n  @@map(\"bolsas_sangue\")\n}\n\nmodel PedidoTransfusao {\n  id             String    @id @default(uuid())\n  doenteId       String\n  prescritoPorId String\n  criadaEm       DateTime  @default(now())\n  updatedAt      DateTime  @updatedAt\n  deletedAt      DateTime?\n\n  componente         String // idem BolsaSangue.componente\n  numeroUnidades     Int     @default(1)\n  grupoABO           String? // grupo do doente (type & screen); pode ainda não estar determinado\n  rhD                String?\n  urgencia           String  @default(\"rotina\") // 'rotina'|'urgente'|'emergencia'\n  indicacao          String  @db.VarChar(500)\n  estado             String  @default(\"pendente\") // 'pendente'|'reservado'|'administrado'|'cancelado'\n  motivoCancelamento String? @db.VarChar(500)\n\n  doente           Doente              @relation(fields: [doenteId], references: [id], onDelete: Cascade)\n  prescritoPor     Utilizador          @relation(\"TransfusoesPrescritas\", fields: [prescritoPorId], references: [id], onDelete: Cascade)\n  bolsasReservadas BolsaSangue[]\n  registos         RegistoTransfusao[]\n\n  @@index([doenteId, criadaEm])\n  @@index([estado])\n  @@map(\"pedidos_transfusao\")\n}\n\nmodel RegistoTransfusao {\n  id                 String    @id @default(uuid())\n  pedidoTransfusaoId String\n  bolsaId            String    @unique\n  doenteId           String\n  administradoPorId  String\n  iniciadoEm         DateTime  @default(now())\n  terminadoEm        DateTime?\n\n  // Dupla verificação de segurança à cabeceira (análogo aos \"5 certos\" do MAR)\n  verificacaoABO      Boolean @default(false) // doente certo + grupo ABO/Rh compatível conferido\n  verificacaoUnidade  Boolean @default(false) // nº da unidade confere com a etiqueta\n  verificacaoValidade Boolean @default(false) // dentro da validade\n  compativel          Boolean // resultado do check de compatibilidade ABO/Rh (calculado em serviço)\n  observacoes         String? @db.VarChar(1000)\n\n  pedido          PedidoTransfusao     @relation(fields: [pedidoTransfusaoId], references: [id], onDelete: Cascade)\n  bolsa           BolsaSangue          @relation(fields: [bolsaId], references: [id], onDelete: Restrict)\n  doente          Doente               @relation(fields: [doenteId], references: [id], onDelete: Cascade)\n  administradoPor Utilizador           @relation(\"TransfusoesAdministradas\", fields: [administradoPorId], references: [id], onDelete: Cascade)\n  reacao          ReacaoTransfusional?\n\n  @@index([doenteId, iniciadoEm])\n  @@map(\"registos_transfusao\")\n}\n\nmodel ReacaoTransfusional {\n  id                  String   @id @default(uuid())\n  registoTransfusaoId String   @unique\n  doenteId            String\n  registadoPorId      String\n  criadaEm            DateTime @default(now())\n\n  tipo                     String // 'febril_nao_hemolitica'|'alergica'|'hemolitica_aguda'|'trali'|'taco'|'contaminacao_bacteriana'|'outra'\n  gravidade                String // 'ligeira'|'moderada'|'grave'|'fatal'\n  sintomas                 String  @db.VarChar(1000)\n  medidas                  String? @db.VarChar(1000)\n  notificadoHemovigilancia Boolean @default(false)\n\n  registo      RegistoTransfusao @relation(fields: [registoTransfusaoId], references: [id], onDelete: Cascade)\n  doente       Doente            @relation(fields: [doenteId], references: [id], onDelete: Cascade)\n  registadoPor Utilizador        @relation(\"ReacoesTransfusRegisto\", fields: [registadoPorId], references: [id], onDelete: Cascade)\n\n  @@index([doenteId, criadaEm])\n  @@map(\"reacoes_transfusionais\")\n}\n\n// ─── Lista de espera de consultas ────────────────────────────────────────────\nmodel ListaEspera {\n  id               String   @id @default(uuid())\n  doenteId         String?\n  nomeDoente       String?\n  medicoId         String?\n  especialidade    String\n  prioridade       String   @default(\"normal\") // 'urgente' | 'alta' | 'normal'\n  estado           String   @default(\"em_espera\") // 'em_espera' | 'contactado' | 'agendado' | 'cancelado'\n  contactoTelefone String?\n  notas            String?  @db.VarChar(500)\n  criadaEm         DateTime @default(now())\n  atualizadaEm     DateTime @updatedAt\n\n  @@index([especialidade, estado, prioridade])\n  @@map(\"lista_espera\")\n}\n\n// ─── Receita eletrónica (SNS / PEM — pronto-para-sandbox) ─────────────────────\n// Registo da submissão de uma prescrição ao sistema nacional (PEM). O cliente é\n// plugável: por defeito usa um mock/simulador; a ligação real à SPMS entra por config.\nmodel ReceitaEletronica {\n  id             String   @id @default(uuid())\n  doenteId       String\n  prescritoPorId String\n  numeroReceita  String?  @unique // nº atribuído pelo PEM\n  codigoDispensa String? // código de acesso/dispensa (PEM)\n  estado         String   @default(\"emitida\") // 'emitida' | 'dispensada' | 'anulada' | 'erro'\n  ambiente       String   @default(\"sandbox\") // 'sandbox' | 'producao'\n  medicamentos   Json // snapshot dos itens prescritos\n  erro           String?\n  dataEmissao    DateTime @default(now())\n  criadaEm       DateTime @default(now())\n\n  @@index([doenteId, criadaEm])\n  @@map(\"receitas_eletronicas\")\n}\n\n// ─── Audit Log ───────────────────────────────────────────────────────────────\n\nmodel AuditLog {\n  id             String      @id @default(uuid())\n  seq            Int         @unique @default(autoincrement())\n  // Nullable + SetNull: uma escrita registada por trigger pode não ter utilizador da app\n  // (ex.: SQL direto → 'system'), e o log de 6 anos tem de sobreviver à remoção do utilizador.\n  // NUNCA pode uma FK do audit fazer falhar a escrita de negócio.\n  utilizadorId   String?\n  utilizador     Utilizador? @relation(fields: [utilizadorId], references: [id], onDelete: SetNull)\n  // Snapshot da identidade no momento (papéis mudam; utilizador pode ser apagado).\n  utilizadorNome String?\n  utilizadorRole String?\n  acao           String\n  entidadeId     String?\n  entidadeTipo   String?\n  detalhes       String?\n  ip             String?\n  userAgent      String?\n  correlationId  String?\n  origem         String      @default(\"app\") // 'app' | 'trigger' | 'system'\n  createdAt      DateTime    @default(now())\n\n  // Hash-de-conteúdo por-linha (independente, sem ordem/lock) — calculado na captura.\n  // A prova de integridade global vive em AuditCheckpoint (append-only + assinado).\n  contentHash String?\n  // Legado da 1.ª iteração (cadeia encadeada) — mantido para as linhas antigas.\n  prevHash    String?\n  hash        String?\n\n  @@index([utilizadorId, createdAt])\n  @@index([createdAt])\n  @@index([entidadeTipo, entidadeId])\n  @@index([correlationId])\n  @@map(\"audit_logs\")\n}\n\n// Anti-replay de códigos TOTP, durável em Postgres (não em Redis). O Postgres já é dependência\n// dura do login (lê o utilizador, escreve o refresh token), pelo que ancorar aqui NÃO acrescenta\n// ponto único de falha — ao contrário do Redis, cuja indisponibilidade bloqueava TODO o staff\n// clínico (fail-closed). `chave` = sha256(scope:secret:code); nunca guarda secret/código em claro.\nmodel TotpConsumido {\n  chave    String   @id\n  expiraEm DateTime\n\n  @@index([expiraEm])\n  @@map(\"totp_consumidos\")\n}\n\n// Eleição de líder para tarefas @Cron: em produção com várias instâncias da API, cada @Cron\n// dispararia em TODAS (relatórios/lembretes/IA duplicados). Uma lease temporal (por nome) garante\n// que só uma instância corre cada tarefa em cada disparo. Alta-escrita de coordenação → sem valor\n// de auditoria (deny-list dos triggers).\nmodel CronLock {\n  nome     String   @id\n  expiraEm DateTime\n\n  @@map(\"cron_locks\")\n}\n\n// Prova de integridade tamper-evident: raízes (Merkle/encadeadas) assinadas sobre intervalos\n// de audit_logs, seladas em diferido pelo checkpointer (com watermark de commit) e ancoradas\n// fora da BD. As linhas de audit_logs nunca são alteradas (WORM) — a prova está aqui.\nmodel AuditCheckpoint {\n  id                 String    @id @default(uuid())\n  seqInicio          Int\n  seqFim             Int\n  raiz               String // raiz Merkle ou hash encadeado dos contentHash do intervalo\n  prevCheckpointHash String? // encadeia os checkpoints entre si\n  assinatura         String? // assinatura da raiz com chave que o DBA não tem\n  totalEntradas      Int\n  ancoradoEm         DateTime? // quando foi replicado para armazenamento externo/WORM\n  criadoEm           DateTime  @default(now())\n\n  @@index([seqFim])\n  @@map(\"audit_checkpoints\")\n}\n\n// Trilho de acessos (LEITURAS) de dados sensíveis. Escrito de forma assíncrona e em lote,\n// SEPARADO do audit de escritas, para não afetar a performance das leituras. Sem cadeia.\nmodel AcessoLeitura {\n  id             String   @id @default(uuid())\n  utilizadorId   String?\n  utilizadorNome String?\n  utilizadorRole String?\n  entidadeTipo   String\n  entidadeId     String?\n  rota           String?\n  ip             String?\n  correlationId  String?\n  createdAt      DateTime @default(now())\n\n  @@index([utilizadorId, createdAt])\n  @@index([entidadeTipo, entidadeId])\n  @@index([createdAt])\n  @@map(\"acessos_leitura\")\n}\n\n// ─── Feature Flags ────────────────────────────────────────────────────────────\n\nmodel FeatureFlag {\n  id              String   @id @default(uuid())\n  key             String   @unique\n  descricao       String?\n  enabled         Boolean  @default(false) // desliga tudo se false\n  rolloutPercent  Int      @default(100) // % de utilizadores (hash determinístico) quando enabled\n  roles           String[] @default([]) // allowlist de roles (vazio = todas)\n  servicos        String[] @default([]) // allowlist de serviços (vazio = todos)\n  atualizadoPorId String?\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n\n  @@map(\"feature_flags\")\n}\n\n// ─── Alergias ─────────────────────────────────────────────────────────────────\n\nmodel Alergia {\n  id         String   @id @default(uuid())\n  doenteId   String\n  doente     Doente   @relation(fields: [doenteId], references: [id], onDelete: Cascade)\n  alergenio  String\n  tipo       String\n  severidade String\n  notas      String?\n  criadaEm   DateTime @default(now())\n\n  @@index([doenteId])\n  @@map(\"alergias\")\n}\n\n// ─── Contactos de Emergência ──────────────────────────────────────────────────\n\nmodel ContactoEmergencia {\n  id        String  @id @default(uuid())\n  doenteId  String\n  doente    Doente  @relation(fields: [doenteId], references: [id], onDelete: Cascade)\n  nome      String\n  relacao   String\n  telefone  String\n  principal Boolean @default(false)\n\n  @@map(\"contactos_emergencia\")\n}\n\n// ─── Alertas Clínicos ─────────────────────────────────────────────────────────\n\nmodel AlertaClinico {\n  id           String      @id @default(uuid())\n  doenteId     String\n  doente       Doente      @relation(fields: [doenteId], references: [id], onDelete: Cascade)\n  tipo         String\n  mensagem     String\n  lido         Boolean     @default(false)\n  urgencia     Boolean     @default(false)\n  acusadoPorId String?\n  acusadoPor   Utilizador? @relation(\"AlertaAcusador\", fields: [acusadoPorId], references: [id], onDelete: SetNull)\n  acusadoEm    DateTime?\n  escaladoEm   DateTime?\n  criadoEm     DateTime    @default(now())\n\n  @@index([doenteId, lido])\n  @@index([doenteId, lido, criadoEm])\n  @@index([criadoEm])\n  @@map(\"alertas_clinicos\")\n}\n\n// ─── Avaliações de Risco Clínico ─────────────────────────────────────────────\n\nmodel AvaliacaoRisco {\n  id             String     @id @default(uuid())\n  doenteId       String\n  doente         Doente     @relation(fields: [doenteId], references: [id], onDelete: Cascade)\n  tipo           String\n  pontuacao      Int\n  itens          Json\n  risco          String\n  registadoPorId String\n  registadoPor   Utilizador @relation(fields: [registadoPorId], references: [id], onDelete: Cascade)\n  criadaEm       DateTime   @default(now())\n\n  @@map(\"avaliacoes_risco\")\n}\n\n// ─── Sumário de Alta ──────────────────────────────────────────────────────────\n\nmodel SumarioAlta {\n  id                String     @id @default(uuid())\n  doenteId          String     @unique\n  doente            Doente     @relation(fields: [doenteId], references: [id], onDelete: Cascade)\n  motivoAlta        String\n  destino           String?\n  resumoClinical    String\n  prescricaoSaida   String?\n  medicoFamilia     String?\n  criadoPorId       String\n  criadoPor         Utilizador @relation(fields: [criadoPorId], references: [id], onDelete: Cascade)\n  criadoEm          DateTime   @default(now())\n  riscReadmissao    String?\n  fatoresReadmissao String?    @db.Text\n  recomendacoesAlta String?    @db.Text\n  cartaAlta         String?    @db.Text\n  icd10Code         String?\n\n  @@map(\"sumarios_alta\")\n}\n\n// ─── Dispositivos / Push Tokens ───────────────────────────────────────────────\n\nmodel DispositivoToken {\n  id           String     @id @default(uuid())\n  utilizadorId String\n  utilizador   Utilizador @relation(fields: [utilizadorId], references: [id], onDelete: Cascade)\n  token        String     @unique\n  plataforma   String\n  criadoEm     DateTime   @default(now())\n\n  @@map(\"dispositivos_tokens\")\n}\n\n// ─── Notificações In-App ──────────────────────────────────────────────────────\n\nmodel NotificacaoInApp {\n  id           String     @id @default(uuid())\n  utilizadorId String\n  utilizador   Utilizador @relation(fields: [utilizadorId], references: [id], onDelete: Cascade)\n  titulo       String\n  corpo        String\n  lida         Boolean    @default(false)\n  dadosExtra   Json?\n  criadaEm     DateTime   @default(now())\n  lidaEm       DateTime?\n\n  @@index([utilizadorId, lida])\n  @@index([utilizadorId, lida, criadaEm])\n  @@index([criadaEm])\n  @@map(\"notificacoes_inapp\")\n}\n\n// ═══════════════════════════════════════════════════════════════════════════════\n// FASE 5 — EXPANSÃO HOSPITALAR\n// ═══════════════════════════════════════════════════════════════════════════════\n\n// ─── Exames Complementares de Diagnóstico ────────────────────────────────────\n\nenum TipoExame {\n  analise_clinica\n  rx\n  eco\n  tc\n  rmn\n  ecg\n  outro\n}\n\nenum EstadoExame {\n  solicitado\n  em_progresso\n  resultado_disponivel\n  cancelado\n}\n\nmodel Exame {\n  id              String      @id @default(uuid())\n  doenteId        String\n  doente          Doente      @relation(fields: [doenteId], references: [id], onDelete: Cascade)\n  solicitadoPorId String\n  solicitadoPor   Utilizador  @relation(\"ExameSolicitadoPor\", fields: [solicitadoPorId], references: [id], onDelete: Cascade)\n  tipo            TipoExame\n  descricao       String\n  urgente         Boolean     @default(false)\n  estado          EstadoExame @default(solicitado)\n  resultado       String?\n  dataResultado   DateTime?\n  observacoes     String?\n  criadoEm        DateTime    @default(now())\n\n  ficheiros FicheiroExame[]\n\n  @@index([estado, urgente])\n  @@index([doenteId, estado])\n  @@map(\"exames\")\n}\n\nmodel FicheiroExame {\n  id       String @id @default(uuid())\n  exameId  String\n  exame    Exame  @relation(fields: [exameId], references: [id], onDelete: Cascade)\n  nome     String\n  url      String\n  mimeType String\n\n  @@map(\"ficheiros_exame\")\n}\n\n// ─── Urgência / Triagem ───────────────────────────────────────────────────────\n\nenum CorTriagem {\n  vermelho\n  laranja\n  amarelo\n  verde\n  azul\n}\n\nenum EstadoEpisodio {\n  triagem\n  sala_espera\n  em_atendimento\n  alta_urgencia\n  internado\n  transferido\n}\n\nmodel EpisodioUrgencia {\n  id                    String         @id @default(uuid())\n  doenteId              String?\n  doente                Doente?        @relation(fields: [doenteId], references: [id], onDelete: SetNull)\n  nomeTemporario        String?\n  queixaPrincipal       String\n  triagem               CorTriagem\n  corAnterior           String? // cor antes da re-triagem\n  estadoEpisodio        EstadoEpisodio @default(sala_espera)\n  triadoPorId           String\n  triadoPor             Utilizador     @relation(\"EpisodioTriador\", fields: [triadoPorId], references: [id], onDelete: Cascade)\n  medicoResponsavelId   String?\n  medicoResponsavel     Utilizador?    @relation(\"EpisodioMedico\", fields: [medicoResponsavelId], references: [id], onDelete: SetNull)\n  dataEntrada           DateTime       @default(now())\n  iniciadoAtendimentoEm DateTime?\n  dataSaida             DateTime?\n  notas                 String?\n  sinaisVitaisTriagem   Json?\n  preNotificacao        Boolean        @default(false)\n  etaMinutos            Int?\n  condicaoPrevia        String?\n  salaAtendimento       String?\n\n  // NEWS2 calculado automaticamente na triagem\n  news2Triagem Int?\n\n  // Dados pré-hospitalares (pré-notificação enriquecida)\n  idadeAproximada Int?\n  sexo            String? // 'masculino' | 'feminino' | 'desconhecido'\n  consciente      Boolean?\n  glasgow         Int? // 3-15\n  mecanismo       String? // 'medico' | 'trauma' | 'intoxicacao' | 'obstetrico' | 'pediatrico'\n\n  // Vitais en route\n  vitalsPASistolica  Int?\n  vitalsPADiastolica Int?\n  vitalsFC           Int?\n  vitalsSpO2         Int?\n  vitalsFR           Int?\n\n  // Intervenções INEM\n  intervencoes String[]\n\n  // Activação de especialidade\n  especialidadeActivada      String? // 'stemi' | 'avc' | 'trauma'\n  especialidadeActivadaEm    DateTime?\n  especialidadeActivadaPorId String?\n  especialidadeActivadaPor   Utilizador? @relation(\"EpisodioEspecialidadeActivadaPor\", fields: [especialidadeActivadaPorId], references: [id], onDelete: SetNull)\n\n  atualizacoes AtualizacaoTransporte[]\n\n  @@index([estadoEpisodio, dataEntrada])\n  @@map(\"episodios_urgencia\")\n}\n\nmodel AtualizacaoTransporte {\n  id             String   @id @default(uuid())\n  episodioId     String\n  registadoPorId String\n  criadaEm       DateTime @default(now())\n  texto          String   @db.VarChar(1000)\n  novaETA        Int?\n\n  episodio     EpisodioUrgencia @relation(fields: [episodioId], references: [id], onDelete: Cascade)\n  registadoPor Utilizador       @relation(\"AtualizacaoTransporteRegistadoPor\", fields: [registadoPorId], references: [id], onDelete: Cascade)\n\n  @@index([episodioId, criadaEm])\n  @@map(\"atualizacoes_transporte\")\n}\n\n// ─── Bloco Operatório ────────────────────────────────────────────────────────\n\nenum EstadoCirurgia {\n  agendada\n  em_curso\n  concluida\n  cancelada\n  adiada\n}\n\nmodel CirurgiaProgramada {\n  id                 String             @id @default(uuid())\n  doenteId           String\n  doente             Doente             @relation(fields: [doenteId], references: [id], onDelete: Cascade)\n  designacao         String\n  dataHora           DateTime\n  duracaoPrevista    Int\n  sala               String\n  estado             EstadoCirurgia     @default(agendada)\n  cirurgiaoId        String\n  cirurgiao          Utilizador         @relation(\"CirurgiaCircurgiao\", fields: [cirurgiaoId], references: [id], onDelete: Cascade)\n  anestesistaId      String?\n  anestesista        Utilizador?        @relation(\"CirurgiaAnestesista\", fields: [anestesistaId], references: [id], onDelete: SetNull)\n  equipa             Json?\n  notasPreOperatorio String?\n  notasPosOperatorio String?\n  complicacoes       String?\n  criadoEm           DateTime           @default(now())\n  checklist          ChecklistCirurgia?\n\n  @@index([dataHora])\n  @@index([estado])\n  @@map(\"cirurgias_programadas\")\n}\n\nmodel ChecklistCirurgia {\n  id         String             @id @default(uuid())\n  cirurgiaId String             @unique\n  cirurgia   CirurgiaProgramada @relation(fields: [cirurgiaId], references: [id], onDelete: Cascade)\n\n  signInEm    DateTime?\n  signInPorId String?\n  signInPor   Utilizador? @relation(\"ChecklistSignIn\", fields: [signInPorId], references: [id], onDelete: SetNull)\n  signInDados Json?\n\n  timeOutEm    DateTime?\n  timeOutPorId String?\n  timeOutPor   Utilizador? @relation(\"ChecklistTimeOut\", fields: [timeOutPorId], references: [id], onDelete: SetNull)\n  timeOutDados Json?\n\n  signOutEm    DateTime?\n  signOutPorId String?\n  signOutPor   Utilizador? @relation(\"ChecklistSignOut\", fields: [signOutPorId], references: [id], onDelete: SetNull)\n  signOutDados Json?\n\n  @@map(\"checklists_cirurgia\")\n}\n\n// ─── Consultas Externas ───────────────────────────────────────────────────────\n\nenum EstadoConsulta {\n  agendada\n  realizada\n  faltou\n  cancelada\n}\n\nmodel Consulta {\n  id                String             @id @default(uuid())\n  doenteId          String?\n  doente            Doente?            @relation(fields: [doenteId], references: [id], onDelete: SetNull)\n  nomeDoente        String?\n  medicoId          String\n  medico            Utilizador         @relation(fields: [medicoId], references: [id], onDelete: Cascade)\n  especialidade     String\n  dataHora          DateTime\n  duracao           Int                @default(30)\n  estado            EstadoConsulta     @default(agendada)\n  notas             String?\n  diagnostico       String?\n  proximaConsulta   DateTime?\n  codigo            String?            @unique\n  checkinEm         DateTime?\n  tipo              String             @default(\"presencial\") // 'presencial' | 'teleconsulta'\n  videoRoomId       String?\n  videoIniciadaEm   DateTime?\n  videoTerminouEm   DateTime?\n  lembreteEnviadoEm DateTime? // quando o lembrete pré-consulta foi enviado (evita duplicados)\n  criadoEm          DateTime           @default(now())\n  atosConsulta      AtoConsulta[]\n  episodioFaturacao EpisodioFaturacao?\n\n  @@index([medicoId, dataHora])\n  @@index([codigo])\n  @@map(\"consultas\")\n}\n\nmodel AgendaMedico {\n  id          String     @id @default(uuid())\n  medicoId    String\n  medico      Utilizador @relation(\"AgendaMedico\", fields: [medicoId], references: [id], onDelete: Cascade)\n  diaSemana   Int // 0=Dom 1=Seg 2=Ter 3=Qua 4=Qui 5=Sex 6=Sab\n  horaInicio  String // \"08:00\"\n  horaFim     String // \"13:00\"\n  duracaoSlot Int        @default(20)\n  ativo       Boolean    @default(true)\n  criadoEm    DateTime   @default(now())\n\n  @@unique([medicoId, diaSemana])\n  @@map(\"agenda_medico\")\n}\n\n// ─── Sala de Espera ───────────────────────────────────────────────────────────\n\nenum EstadoCheckin {\n  aguardando\n  em_atendimento\n  atendido\n  desistiu\n  ausente\n}\n\nmodel CheckinSalaEspera {\n  id                  String        @id @default(uuid())\n  nomeDoente          String\n  dataNascimento      DateTime?\n  numeroUtente        String?\n  motivo              String\n  prioridade          Int           @default(3)\n  estado              EstadoCheckin @default(aguardando)\n  chegadaEm           DateTime      @default(now())\n  chamadoEm           DateTime?\n  atendidoEm          DateTime?\n  rececionistadoPorId String?\n  rececionista        Utilizador?   @relation(\"CheckinRececionista\", fields: [rececionistadoPorId], references: [id], onDelete: SetNull)\n  medicoId            String?\n  medico              Utilizador?   @relation(\"CheckinMedico\", fields: [medicoId], references: [id], onDelete: SetNull)\n  observacoes         String?\n\n  @@index([estado, chegadaEm])\n  @@map(\"checkins_sala_espera\")\n}\n\n// ─── Farmácia / Stock ─────────────────────────────────────────────────────────\n\nenum TipoStock {\n  medicamento\n  material\n  consumivel\n}\n\nenum EstadoPedidoFarmacia {\n  pendente\n  aprovado\n  rejeitado\n  dispensado\n  cancelado\n}\n\nmodel StockItem {\n  id               String               @id @default(uuid())\n  nome             String\n  tipo             TipoStock\n  quantidade       Float                @default(0)\n  quantidadeMinima Float                @default(0)\n  unidade          String\n  validade         DateTime?\n  servico          String\n  precoUnitario    Float?\n  catalogoId       String?\n  catalogo         CatalogoMedicamento? @relation(fields: [catalogoId], references: [id], onDelete: SetNull)\n  criadoEm         DateTime             @default(now())\n\n  pedidos        PedidoFarmacia[]\n  ajustes        AjusteStock[]\n  transferencias TransferenciaStock[]\n  encomendas     EncomendaFornecedor[]\n\n  @@index([catalogoId])\n  @@index([servico])\n  @@map(\"stock_items\")\n}\n\nmodel PedidoFarmacia {\n  id              String               @id @default(uuid())\n  stockItemId     String\n  stockItem       StockItem            @relation(fields: [stockItemId], references: [id], onDelete: Cascade)\n  quantidade      Float\n  servico         String\n  estado          EstadoPedidoFarmacia @default(pendente)\n  solicitadoPorId String\n  solicitadoPor   Utilizador           @relation(\"PedidoSolicitante\", fields: [solicitadoPorId], references: [id], onDelete: Cascade)\n  processadoPorId String?\n  processadoPor   Utilizador?          @relation(\"PedidoProcessador\", fields: [processadoPorId], references: [id], onDelete: SetNull)\n  aprovadoPorId   String?\n  aprovadoPor     Utilizador?          @relation(\"PedidoAprovador\", fields: [aprovadoPorId], references: [id], onDelete: SetNull)\n  aprovadoEm      DateTime?\n  motivoRejeicao  String?\n  observacoes     String?\n  criadoEm        DateTime             @default(now())\n\n  @@index([estado, criadoEm])\n  @@map(\"pedidos_farmacia\")\n}\n\nmodel CatalogoMedicamento {\n  id                String   @id @default(uuid())\n  dci               String\n  nomeMarca         String?\n  formaFarmaceutica String\n  classeTerap       String\n  unidade           String\n  concentracao      String?\n  codigoATC         String?\n  ativo             Boolean  @default(true)\n  criadoEm          DateTime @default(now())\n\n  stockItems StockItem[]\n\n  @@map(\"catalogo_medicamentos\")\n}\n\nmodel AjusteStock {\n  id           String     @id @default(uuid())\n  stockItemId  String\n  stockItem    StockItem  @relation(fields: [stockItemId], references: [id], onDelete: Cascade)\n  delta        Float\n  tipo         String // \"entrada\" | \"saida\" | \"ajuste\" | \"desperdicio\" | \"validade\" | \"encomenda\" | \"transferencia\"\n  motivo       String\n  utilizadorId String\n  utilizador   Utilizador @relation(\"AjustesFeitos\", fields: [utilizadorId], references: [id], onDelete: Cascade)\n  criadoEm     DateTime   @default(now())\n\n  @@index([stockItemId])\n  @@index([criadoEm])\n  @@map(\"ajustes_stock\")\n}\n\nmodel TransferenciaStock {\n  id              String      @id @default(uuid())\n  stockItemId     String\n  stockItem       StockItem   @relation(fields: [stockItemId], references: [id], onDelete: Cascade)\n  quantidade      Float\n  servicoOrigem   String\n  servicoDestino  String\n  motivo          String?\n  estado          String      @default(\"pendente\") // pendente | confirmada | cancelada\n  solicitadoPorId String\n  solicitadoPor   Utilizador  @relation(\"TransfSolicitadas\", fields: [solicitadoPorId], references: [id], onDelete: Cascade)\n  confirmadoPorId String?\n  confirmadoPor   Utilizador? @relation(\"TransfConfirmadas\", fields: [confirmadoPorId], references: [id], onDelete: SetNull)\n  criadoEm        DateTime    @default(now())\n  atualizadoEm    DateTime    @updatedAt\n\n  @@index([stockItemId])\n  @@map(\"transferencias_stock\")\n}\n\nmodel Fornecedor {\n  id       String   @id @default(uuid())\n  nome     String\n  nif      String?  @unique\n  email    String?\n  telefone String?\n  morada   String?\n  ativo    Boolean  @default(true)\n  criadoEm DateTime @default(now())\n\n  encomendas EncomendaFornecedor[]\n\n  @@map(\"fornecedores\")\n}\n\nmodel EncomendaFornecedor {\n  id                    String      @id @default(uuid())\n  fornecedorId          String\n  fornecedor            Fornecedor  @relation(fields: [fornecedorId], references: [id], onDelete: Cascade)\n  stockItemId           String\n  stockItem             StockItem   @relation(fields: [stockItemId], references: [id], onDelete: Cascade)\n  quantidadeEncomendada Float\n  precoUnitario         Float?\n  estado                String      @default(\"pendente\") // pendente | recebida | parcial | cancelada\n  dataEntregaPrevista   DateTime?\n  dataEntregaReal       DateTime?\n  observacoes           String?\n  recebioPorId          String?\n  recebioPor            Utilizador? @relation(\"EncomendasRecebidas\", fields: [recebioPorId], references: [id], onDelete: SetNull)\n  criadoEm              DateTime    @default(now())\n  atualizadoEm          DateTime    @updatedAt\n\n  @@index([fornecedorId])\n  @@index([stockItemId])\n  @@map(\"encomendas_fornecedor\")\n}\n\n// ─── Fisioterapia / Reabilitação ──────────────────────────────────────────────\n\nmodel PlanoReabilitacao {\n  id               String     @id @default(uuid())\n  doenteId         String\n  doente           Doente     @relation(fields: [doenteId], references: [id], onDelete: Cascade)\n  fisioterapeutaId String\n  fisioterapeuta   Utilizador @relation(fields: [fisioterapeutaId], references: [id], onDelete: Cascade)\n  objetivos        String\n  dataInicio       DateTime\n  dataFimPrevista  DateTime?\n  ativo            Boolean    @default(true)\n  criadoEm         DateTime   @default(now())\n\n  sessoes SessaoFisioterapia[]\n\n  @@map(\"planos_reabilitacao\")\n}\n\nenum EstadoSessao {\n  agendada\n  realizada\n  cancelada\n  faltou\n}\n\nmodel SessaoFisioterapia {\n  id               String            @id @default(uuid())\n  planoId          String\n  plano            PlanoReabilitacao @relation(fields: [planoId], references: [id], onDelete: Cascade)\n  doenteId         String\n  doente           Doente            @relation(fields: [doenteId], references: [id], onDelete: Cascade)\n  fisioterapeutaId String\n  fisioterapeuta   Utilizador        @relation(fields: [fisioterapeutaId], references: [id], onDelete: Cascade)\n  data             DateTime\n  duracao          Int\n  descricao        String\n  evolucao         String?\n  estado           EstadoSessao      @default(agendada)\n\n  @@map(\"sessoes_fisioterapia\")\n}\n\n// ─── Pedidos Internos ────────────────────────────────────────────────────────\n\nenum TipoPedidoInterno {\n  transporte\n  esterilizacao\n  equipamento\n  limpeza\n}\n\nenum EstadoPedidoInterno {\n  pendente\n  em_curso\n  concluido\n  cancelado\n}\n\nmodel PedidoInterno {\n  id              String              @id @default(uuid())\n  tipo            TipoPedidoInterno\n  doenteId        String?\n  doente          Doente?             @relation(fields: [doenteId], references: [id], onDelete: SetNull)\n  localOrigem     String?\n  localDestino    String?\n  descricao       String\n  prioridade      PrioridadeTarefa\n  estado          EstadoPedidoInterno @default(pendente)\n  solicitadoPorId String\n  solicitadoPor   Utilizador          @relation(\"PedidoInternoSolicitante\", fields: [solicitadoPorId], references: [id], onDelete: Cascade)\n  executadoPorId  String?\n  executadoPor    Utilizador?         @relation(\"PedidoInternoExecutor\", fields: [executadoPorId], references: [id], onDelete: SetNull)\n  servicoOrigem   String\n  criadoEm        DateTime            @default(now())\n  concluidoEm     DateTime?\n\n  @@index([estado, criadoEm])\n  @@map(\"pedidos_internos\")\n}\n\n// ─── Comunicação Interna ──────────────────────────────────────────────────────\n\nmodel Anuncio {\n  id       String     @id @default(uuid())\n  autorId  String\n  autor    Utilizador @relation(fields: [autorId], references: [id], onDelete: Cascade)\n  titulo   String\n  texto    String\n  servico  String?\n  ativo    Boolean    @default(true)\n  criadoEm DateTime   @default(now())\n  expiraEm DateTime?\n\n  @@map(\"anuncios\")\n}\n\nmodel MensagemInterna {\n  id             String          @id @default(uuid())\n  remetenteId    String\n  remetente      Utilizador      @relation(\"MensagemRemetente\", fields: [remetenteId], references: [id], onDelete: Cascade)\n  destinatarioId String\n  destinatario   Utilizador      @relation(\"MensagemDestinatario\", fields: [destinatarioId], references: [id], onDelete: Cascade)\n  assunto        String?\n  texto          String\n  lida           Boolean         @default(false)\n  criadaEm       DateTime        @default(now())\n  anexos         AnexoMensagem[]\n\n  @@index([destinatarioId, lida])\n  @@index([remetenteId])\n  @@map(\"mensagens_internas\")\n}\n\nmodel AnexoMensagem {\n  id         String          @id @default(uuid())\n  mensagemId String\n  mensagem   MensagemInterna @relation(fields: [mensagemId], references: [id], onDelete: Cascade)\n  nome       String\n  url        String\n  mimeType   String\n  tamanho    Int\n  criadoEm   DateTime        @default(now())\n\n  @@index([mensagemId])\n  @@map(\"anexos_mensagem\")\n}\n\n// ─── Interconsultas ──────────────────────────────────────────────────────────\n\nenum EstadoInterconsulta {\n  pendente\n  aceite\n  respondida\n  cancelada\n}\n\nmodel Interconsulta {\n  id                String              @id @default(uuid())\n  doenteId          String\n  doente            Doente              @relation(fields: [doenteId], references: [id], onDelete: Cascade)\n  requisitanteId    String\n  requisitante      Utilizador          @relation(\"InterconsultaRequisitante\", fields: [requisitanteId], references: [id], onDelete: Cascade)\n  especialidadeAlvo String\n  motivo            String\n  urgente           Boolean             @default(false)\n  estado            EstadoInterconsulta @default(pendente)\n  medicoRespostaId  String?\n  medicoResposta    Utilizador?         @relation(\"InterconsultaResposta\", fields: [medicoRespostaId], references: [id], onDelete: SetNull)\n  resposta          String?\n  criadaEm          DateTime            @default(now())\n  respondidaEm      DateTime?\n\n  @@index([doenteId])\n  @@index([especialidadeAlvo, estado])\n  @@index([requisitanteId, estado])\n  @@map(\"interconsultas\")\n}\n\n// ─── Dispositivos Invasivos ──────────────────────────────────────────────────\n\nenum TipoDispositivoInvasivo {\n  cateter_venoso_central\n  cateter_venoso_periferico\n  cateter_arterial\n  sonda_vesical\n  tubo_orotaqueal\n  traqueostomia\n  dreno_toracico\n  sonda_nasogastrica\n  linha_epidural\n  outro\n}\n\nmodel DispositivoInvasivo {\n  id            String                  @id @default(uuid())\n  doenteId      String\n  doente        Doente                  @relation(fields: [doenteId], references: [id], onDelete: Cascade)\n  tipo          TipoDispositivoInvasivo\n  localizacao   String?\n  dataInsercao  DateTime                @default(now())\n  dataRemocao   DateTime?\n  ativo         Boolean                 @default(true)\n  observacoes   String?\n  inseridoPorId String\n  inseridoPor   Utilizador              @relation(\"DispositivoInserido\", fields: [inseridoPorId], references: [id], onDelete: Cascade)\n\n  @@index([doenteId, ativo])\n  @@map(\"dispositivos_invasivos\")\n}\n\n// ─── Incidentes TI ───────────────────────────────────────────────────────────\n\nenum TipoIncidenteTI {\n  infraestrutura\n  rede\n  his_erp\n  base_dados\n  seguranca\n  dados_clinicos\n  outro\n}\n\nenum EstadoIncidenteTI {\n  aberto\n  em_analise\n  resolvido\n  fechado\n}\n\nenum PrioridadeIncidenteTI {\n  baixa\n  media\n  alta\n  critica\n}\n\nmodel IncidenteTI {\n  id            String                @id @default(uuid())\n  titulo        String\n  descricao     String\n  tipo          TipoIncidenteTI\n  subRoleAlvo   String?\n  prioridade    PrioridadeIncidenteTI @default(media)\n  estado        EstadoIncidenteTI     @default(aberto)\n  criadoPorId   String\n  criadoPor     Utilizador            @relation(\"IncidentesCriados\", fields: [criadoPorId], references: [id], onDelete: Cascade)\n  responsavelId String?\n  responsavel   Utilizador?           @relation(\"IncidentesAtribuidos\", fields: [responsavelId], references: [id], onDelete: SetNull)\n  criadoEm      DateTime              @default(now())\n  atualizadoEm  DateTime              @updatedAt\n  notas         NotaIncidenteTI[]\n\n  @@index([estado])\n  @@index([subRoleAlvo])\n  @@map(\"incidentes_ti\")\n}\n\nmodel NotaIncidenteTI {\n  id          String      @id @default(uuid())\n  incidenteId String\n  incidente   IncidenteTI @relation(fields: [incidenteId], references: [id], onDelete: Cascade)\n  autorId     String\n  autor       Utilizador  @relation(\"NotasIncidentesTI\", fields: [autorId], references: [id], onDelete: Cascade)\n  conteudo    String\n  criadaEm    DateTime    @default(now())\n\n  @@index([incidenteId])\n  @@map(\"notas_incidentes_ti\")\n}\n\n// ─── Pedidos TI ───────────────────────────────────────────────────────────────\n\nenum TipoPedidoTI {\n  listagem_dados\n  relatorio\n  acesso_sistema\n  backup\n  auditoria_dados\n  outro\n}\n\nenum EstadoPedidoTI {\n  pendente\n  em_curso\n  concluido\n  recusado\n}\n\nmodel PedidoTI {\n  id          String         @id @default(cuid())\n  titulo      String\n  descricao   String\n  tipo        TipoPedidoTI\n  estado      EstadoPedidoTI @default(pendente)\n  urgente     Boolean        @default(false)\n  criadoEm    DateTime       @default(now())\n  resolvidoEm DateTime?\n\n  criadoPorId String\n  criadoPor   Utilizador @relation(\"PedidosTICriados\", fields: [criadoPorId], references: [id], onDelete: Cascade)\n\n  responsavelId String?\n  responsavel   Utilizador? @relation(\"PedidosTIAtribuidos\", fields: [responsavelId], references: [id], onDelete: SetNull)\n\n  @@index([estado])\n  @@index([criadoPorId])\n  @@map(\"pedidos_ti\")\n}\n\n// ─── Ficha Pessoal do Doente (acesso restrito: só role 'administrativo') ──────\n\nmodel FicheiroPessoalDoente {\n  id                 String      @id @default(uuid())\n  doenteId           String      @unique\n  doente             Doente      @relation(fields: [doenteId], references: [id], onDelete: Cascade)\n  nif                String?\n  numeroSNS          String?\n  morada             String?\n  codigoPostal       String?\n  localidade         String?\n  telefone           String?\n  email              String?\n  entidadeSeguradora String?\n  numeroApolice      String?\n  tipoCobertura      String? // 'sns' | 'seguro' | 'particular'\n  atualizadoEm       DateTime    @updatedAt\n  atualizadoPorId    String?\n  atualizadoPor      Utilizador? @relation(fields: [atualizadoPorId], references: [id], onDelete: SetNull)\n\n  @@map(\"fichas_pessoais_doente\")\n}\n\n// ─── Faturação ────────────────────────────────────────────────────────────────\n\nenum EstadoFatura {\n  pendente\n  emitida\n  paga\n  isenta\n  anulada\n}\n\nmodel EpisodioFaturacao {\n  id            String       @id @default(uuid())\n  doenteId      String\n  doente        Doente       @relation(fields: [doenteId], references: [id], onDelete: Cascade)\n  consultaId    String?      @unique\n  consulta      Consulta?    @relation(fields: [consultaId], references: [id], onDelete: SetNull)\n  estado        EstadoFatura @default(pendente)\n  dataEmissao   DateTime?\n  totalBase     Float        @default(0)\n  totalCobrado  Float        @default(0)\n  tipoCobertura String?\n  notas         String?\n  criadoPorId   String\n  criadoPor     Utilizador   @relation(fields: [criadoPorId], references: [id], onDelete: Cascade)\n  criadoEm      DateTime     @default(now())\n  itens         ItemFatura[]\n  pagamentos    Pagamento[]\n\n  @@index([doenteId])\n  @@index([estado])\n  @@map(\"episodios_faturacao\")\n}\n\nmodel ItemFatura {\n  id                  String            @id @default(uuid())\n  episodioFaturacaoId String\n  episodio            EpisodioFaturacao @relation(fields: [episodioFaturacaoId], references: [id], onDelete: Cascade)\n  descricao           String\n  categoria           String // 'diaria' | 'procedimento' | 'medicacao' | 'exame' | 'outro'\n  quantidade          Int               @default(1)\n  precoUnitario       Float\n  total               Float\n  criadoEm            DateTime          @default(now())\n\n  @@map(\"itens_fatura\")\n}\n\nmodel Pagamento {\n  id                  String            @id @default(uuid())\n  episodioFaturacaoId String\n  episodio            EpisodioFaturacao @relation(fields: [episodioFaturacaoId], references: [id], onDelete: Cascade)\n  valor               Float\n  metodo              String // 'numerario' | 'multibanco' | 'transferencia' | 'seguro' | 'isencao'\n  referencia          String?\n  registadoPorId      String\n  registadoPor        Utilizador        @relation(fields: [registadoPorId], references: [id], onDelete: Cascade)\n  criadoEm            DateTime          @default(now())\n\n  @@map(\"pagamentos\")\n}\n\n// ─── Catálogo de Atos Clínicos ───────────────────────────────────────────────\n\nmodel AtoClinico {\n  id            String        @id @default(uuid())\n  codigo        String        @unique\n  descricao     String\n  categoria     String // 'consulta' | 'exame' | 'procedimento' | 'medicacao' | 'outro'\n  precoBase     Float\n  especialidade String? // se definido, é o ato-base automático desta especialidade\n  ativo         Boolean       @default(true)\n  criadoEm      DateTime      @default(now())\n  atosConsulta  AtoConsulta[]\n\n  @@map(\"atos_clinicos\")\n}\n\nmodel AtoConsulta {\n  id            String     @id @default(uuid())\n  consultaId    String\n  consulta      Consulta   @relation(fields: [consultaId], references: [id], onDelete: Cascade)\n  atoId         String\n  ato           AtoClinico @relation(fields: [atoId], references: [id], onDelete: Cascade)\n  quantidade    Int        @default(1)\n  precoUnitario Float\n  criadoEm      DateTime   @default(now())\n\n  @@map(\"atos_consulta\")\n}\n\n// ─── Tickets / Filas de Espera ───────────────────────────────────────────────\n\nmodel Ticket {\n  id          String    @id @default(uuid())\n  numero      String // ex: 'A045', 'C012'\n  letra       String // 'A' | 'C' | 'F' | 'R' | 'E' | 'U' | 'G'\n  sequencia   Int\n  tipo        String // admissao | consulta | faturacao | farmacia | exames | urgencia | geral\n  estado      String    @default(\"aguarda\") // aguarda | chamado | em_atendimento | concluido | desistiu\n  prioridade  String    @default(\"normal\") // normal | prioritario | senior\n  balcao      String?\n  nomeUtente  String?\n  telefone    String?\n  criadoEm    DateTime  @default(now())\n  chamadoEm   DateTime?\n  concluidoEm DateTime?\n\n  @@index([estado, criadoEm])\n  @@index([tipo, criadoEm])\n  @@map(\"tickets\")\n}\n\n// ─── Refresh Tokens ──────────────────────────────────────────────────────────\n\nmodel RefreshToken {\n  id           String     @id @default(uuid())\n  token        String     @unique\n  utilizadorId String\n  utilizador   Utilizador @relation(fields: [utilizadorId], references: [id], onDelete: Cascade)\n  expiresAt    DateTime\n  revogado     Boolean    @default(false)\n  criadoEm     DateTime   @default(now())\n\n  @@index([utilizadorId])\n  @@index([token])\n  @@map(\"refresh_tokens\")\n}\n\n// ─── Problemas Clínicos ──────────────────────────────────────────────────────\n\nmodel ProblemaClinico {\n  id             String     @id @default(uuid())\n  doenteId       String\n  doente         Doente     @relation(fields: [doenteId], references: [id], onDelete: Cascade)\n  descricao      String\n  tipo           String // 'principal' | 'comorbilidade' | 'cirurgico' | 'cronico' | 'agudo'\n  estado         String     @default(\"ativo\") // 'ativo' | 'resolvido' | 'cronico'\n  dataInicio     DateTime?\n  dataFim        DateTime?\n  registadoPorId String\n  registadoPor   Utilizador @relation(\"ProblemaRegistado\", fields: [registadoPorId], references: [id], onDelete: Cascade)\n  criadoEm       DateTime   @default(now())\n\n  @@index([doenteId])\n  @@map(\"problemas_clinicos\")\n}\n\n// ─── Equipamentos e Manutenção ───────────────────────────────────────────────\n\nmodel Equipamento {\n  id                String       @id @default(uuid())\n  nome              String\n  tipo              String // 'cama_eletrica'|'ventilador'|'monitor'|'cadeira_rodas'|'bomba_perfusao'|'desfibrilhador'|'outro'\n  numeroSerie       String?\n  localizacao       String?\n  estado            String       @default(\"operacional\") // 'operacional'|'em_manutencao'|'avariado'|'abatido'\n  ultimaManutencao  DateTime?\n  proximaManutencao DateTime?\n  criadoEm          DateTime     @default(now())\n  manutencoes       Manutencao[]\n\n  @@index([estado])\n  @@map(\"equipamentos\")\n}\n\nmodel Manutencao {\n  id             String      @id @default(uuid())\n  equipamentoId  String\n  equipamento    Equipamento @relation(fields: [equipamentoId], references: [id], onDelete: Cascade)\n  tipo           String // 'preventiva' | 'corretiva'\n  descricao      String\n  estado         String      @default(\"pendente\") // 'pendente'|'em_curso'|'concluida'|'cancelada'\n  prioridade     String      @default(\"normal\") // 'urgente'|'alta'|'normal'|'baixa'\n  reportadoPorId String?\n  reportadoPor   Utilizador? @relation(\"ManutencaoReportada\", fields: [reportadoPorId], references: [id], onDelete: SetNull)\n  tecnicoId      String?\n  tecnico        Utilizador? @relation(\"ManutencaoTecnico\", fields: [tecnicoId], references: [id], onDelete: SetNull)\n  dataReporte    DateTime    @default(now())\n  dataConclusao  DateTime?\n  observacoes    String?\n\n  @@index([equipamentoId])\n  @@index([estado])\n  @@map(\"manutencoes\")\n}\n\n// ─── RH ──────────────────────────────────────────────────────────────────────\n\nmodel Ausencia {\n  id            String      @id @default(uuid())\n  utilizadorId  String\n  utilizador    Utilizador  @relation(\"AusenciaUtilizador\", fields: [utilizadorId], references: [id], onDelete: Cascade)\n  tipo          String // 'ferias'|'baixa_medica'|'licenca_maternidade'|'falta_justificada'|'outro'\n  dataInicio    DateTime\n  dataFim       DateTime\n  estado        String      @default(\"pendente\") // 'pendente'|'aprovada'|'rejeitada'\n  observacoes   String?\n  aprovadoPorId String?\n  aprovadoPor   Utilizador? @relation(\"AusenciaAprovador\", fields: [aprovadoPorId], references: [id], onDelete: SetNull)\n  criadoEm      DateTime    @default(now())\n  atualizadoEm  DateTime    @updatedAt\n\n  @@index([utilizadorId])\n  @@index([estado])\n  @@map(\"ausencias\")\n}\n\nmodel TrocaFolga {\n  id             String   @id @default(uuid())\n  solicitanteId  String\n  destinatarioId String\n  dataOrigem     DateTime // dia do solicitante (folga a ceder)\n  dataDestino    DateTime // dia do destinatário (folga a ceder)\n  motivo         String?\n  estado         String   @default(\"pendente\") // pendente|aceite|recusado|aprovado|cancelado\n  aprovadoPorId  String?\n  criadoEm       DateTime @default(now())\n  atualizadoEm   DateTime @updatedAt\n\n  solicitante  Utilizador  @relation(\"TrocaFolgaSolicitante\", fields: [solicitanteId], references: [id], onDelete: Cascade)\n  destinatario Utilizador  @relation(\"TrocaFolgaDestinatario\", fields: [destinatarioId], references: [id], onDelete: Cascade)\n  aprovadoPor  Utilizador? @relation(\"TrocaFolgaAprovador\", fields: [aprovadoPorId], references: [id], onDelete: SetNull)\n\n  @@index([solicitanteId])\n  @@index([destinatarioId])\n  @@index([estado])\n  @@map(\"trocas_folga\")\n}\n\nmodel FormacaoUtilizador {\n  id             String     @id @default(uuid())\n  utilizadorId   String\n  utilizador     Utilizador @relation(\"FormacaoUtilizador\", fields: [utilizadorId], references: [id], onDelete: Cascade)\n  nome           String\n  dataRealizacao DateTime\n  dataExpiracao  DateTime?\n  entidade       String?\n  obrigatoria    Boolean    @default(false)\n  criadoEm       DateTime   @default(now())\n\n  @@index([utilizadorId])\n  @@map(\"formacoes_utilizadores\")\n}\n\n// ─── Eventos Adversos ─────────────────────────────────────────────────────────\n\nmodel EventoAdverso {\n  id             String      @id @default(uuid())\n  tipo           String // 'queda' | 'erro_medicacao' | 'near_miss' | 'infecao' | 'lesao_pressao' | 'outro'\n  gravidade      String // 'sem_dano' | 'dano_leve' | 'dano_moderado' | 'dano_grave' | 'obito'\n  descricao      String\n  servicoId      String? // servico onde ocorreu (enum Servico como string)\n  doenteId       String?\n  doente         Doente?     @relation(\"EventosAdversosDoente\", fields: [doenteId], references: [id], onDelete: SetNull)\n  registadoPorId String?\n  registadoPor   Utilizador? @relation(\"EventoAdversoRegistado\", fields: [registadoPorId], references: [id], onDelete: SetNull)\n  acaoCorretiva  String?\n  estado         String      @default(\"aberto\") // 'aberto' | 'em_investigacao' | 'encerrado'\n  ocorridoEm     DateTime    @default(now())\n  criadoEm       DateTime    @default(now())\n  atualizadoEm   DateTime    @updatedAt\n\n  @@index([tipo])\n  @@index([gravidade])\n  @@index([estado])\n  @@index([ocorridoEm])\n  @@map(\"eventos_adversos\")\n}\n\n// ─── Especialidades Clínicas (Nutrição, Psicologia, Terapia da Fala, TAE) ────\n\nmodel SessaoEspecialidade {\n  id             String   @id @default(uuid())\n  tipo           String // 'nutricao' | 'psicologia' | 'terapia_fala' | 'tae'\n  doenteId       String\n  profissionalId String\n  data           DateTime\n  duracao        Int // minutos\n  descricao      String?\n  evolucao       String?\n  estado         String   @default(\"agendada\") // agendada | realizada | cancelada | faltou\n  criadoEm       DateTime @default(now())\n\n  doente       Doente     @relation(fields: [doenteId], references: [id], onDelete: Cascade)\n  profissional Utilizador @relation(\"SessaoEspecialidadeProfissional\", fields: [profissionalId], references: [id], onDelete: Cascade)\n\n  @@index([profissionalId, data])\n  @@index([doenteId])\n  @@map(\"sessoes_especialidade\")\n}\n\n// ─── RH Expandido ─────────────────────────────────────────────────────────────\n\nmodel AvaliacaoDesempenho {\n  id             String   @id @default(uuid())\n  utilizadorId   String\n  avaliadorId    String\n  periodo        String // \"2025-Anual\", \"2026-S1\"\n  dataAvaliacao  DateTime\n  pontuacaoGeral Int // 1-5\n  pontosFortes   String?\n  areasMelhoria  String?\n  observacoes    String?\n  estado         String   @default(\"rascunho\") // rascunho | finalizada | assinada\n  criadoEm       DateTime @default(now())\n\n  utilizador Utilizador @relation(\"AvaliacaoAvaliado\", fields: [utilizadorId], references: [id], onDelete: Cascade)\n  avaliador  Utilizador @relation(\"AvaliacaoAvaliador\", fields: [avaliadorId], references: [id], onDelete: Cascade)\n\n  @@index([utilizadorId])\n  @@index([avaliadorId])\n  @@map(\"avaliacoes_desempenho\")\n}\n\nmodel DadosContratuais {\n  id               String    @id @default(uuid())\n  utilizadorId     String    @unique\n  tipoVinculo      String // 'permanente' | 'termo_certo' | 'prestacao_servicos' | 'estagio'\n  dataInicio       DateTime\n  dataFimPrevista  DateTime?\n  diasFeriasAnuais Int       @default(22)\n  criadoEm         DateTime  @default(now())\n  atualizadoEm     DateTime  @updatedAt\n\n  utilizador Utilizador @relation(fields: [utilizadorId], references: [id], onDelete: Cascade)\n\n  @@map(\"dados_contratuais\")\n}\n\n// ─── Consentimento Informado ──────────────────────────────────────────────────\n\nmodel ConsentimentoInformado {\n  id                   String      @id @default(uuid())\n  doenteId             String\n  doente               Doente      @relation(fields: [doenteId], references: [id], onDelete: Cascade)\n  tipo                 String // cirurgia | procedimento_invasivo | anestesia | transfusao | outro\n  descricao            String\n  assinadoDoenteEm     DateTime?\n  assinadoTestemunhaEm DateTime?\n  testemunhaId         String?\n  testemunha           Utilizador? @relation(\"ConsentimentoTestemunha\", fields: [testemunhaId], references: [id], onDelete: SetNull)\n  recusado             Boolean     @default(false)\n  motivoRecusa         String?\n  criadoEm             DateTime    @default(now())\n  criadoPorId          String\n  criadoPor            Utilizador  @relation(\"ConsentimentoCriador\", fields: [criadoPorId], references: [id], onDelete: Cascade)\n\n  @@index([doenteId])\n  @@index([tipo])\n  @@map(\"consentimentos_informados\")\n}\n\n// ─── Break-Glass Access ───────────────────────────────────────────────────────\n\nmodel BreakGlassAccess {\n  id           String     @id @default(uuid())\n  utilizadorId String\n  utilizador   Utilizador @relation(fields: [utilizadorId], references: [id], onDelete: Cascade)\n  doenteId     String\n  doente       Doente     @relation(fields: [doenteId], references: [id], onDelete: Cascade)\n  motivo       String\n  ip           String?\n  ativo        Boolean    @default(true)\n  criadoEm     DateTime   @default(now())\n  expiradoEm   DateTime\n\n  @@index([utilizadorId, doenteId, ativo])\n  @@index([expiradoEm])\n  @@map(\"break_glass_access\")\n}\n\n// ─── Protocolos Clínicos ──────────────────────────────────────────────────────\n\nmodel ProtocoloClinico {\n  id           String          @id @default(uuid())\n  doenteId     String\n  doente       Doente          @relation(fields: [doenteId], references: [id], onDelete: Cascade)\n  tipo         String // sepsis | avc | iamcst | outro\n  estadoGeral  String          @default(\"ativo\") // ativo | concluido | cancelado\n  ativadoPorId String?\n  ativadoPor   Utilizador?     @relation(fields: [ativadoPorId], references: [id], onDelete: SetNull)\n  criadoEm     DateTime        @default(now())\n  itens        ItemProtocolo[]\n\n  @@index([doenteId, estadoGeral])\n  @@index([tipo, estadoGeral])\n  @@map(\"protocolos_clinicos\")\n}\n\nmodel ItemProtocolo {\n  id             String           @id @default(uuid())\n  protocoloId    String\n  protocolo      ProtocoloClinico @relation(fields: [protocoloId], references: [id], onDelete: Cascade)\n  descricao      String\n  prazo          Int? // minutos desde criação do protocolo\n  concluido      Boolean          @default(false)\n  concluidoEm    DateTime?\n  concluidoPorId String?\n  concluidoPor   Utilizador?      @relation(fields: [concluidoPorId], references: [id], onDelete: SetNull)\n\n  @@index([protocoloId])\n  @@map(\"itens_protocolo\")\n}\n\n// ─── Dietética ────────────────────────────────────────────────────────────────\n\nmodel PrescricaoDieta {\n  id          String     @id @default(uuid())\n  doenteId    String\n  doente      Doente     @relation(fields: [doenteId], references: [id], onDelete: Cascade)\n  tipo        String // normal | hipocalorica | diab | renal | hepatica | liquida | jejum | outra\n  restricoes  String[]\n  observacoes String?\n  ativa       Boolean    @default(true)\n  criadaEm    DateTime   @default(now())\n  criadaPorId String\n  criadaPor   Utilizador @relation(fields: [criadaPorId], references: [id], onDelete: Cascade)\n\n  @@index([doenteId, ativa])\n  @@map(\"prescricoes_dieta\")\n}\n\n// ─── IACS — Culturas Microbiológicas e Surtos ─────────────────────────────────\n\nenum ResultadoCultura {\n  pendente\n  positivo\n  negativo\n  contaminado\n}\n\nmodel CulturaMicrobiologica {\n  id             String           @id @default(uuid())\n  doenteId       String\n  doente         Doente           @relation(fields: [doenteId], references: [id], onDelete: Cascade)\n  dataColheita   DateTime\n  tipoAmostra    String\n  agente         String?\n  antibiograma   Json?\n  resultado      ResultadoCultura @default(pendente)\n  servico        String?\n  observacoes    String?\n  registadoPorId String\n  registadoPor   Utilizador       @relation(fields: [registadoPorId], references: [id], onDelete: Cascade)\n  criadoEm       DateTime         @default(now())\n\n  @@index([doenteId])\n  @@index([resultado])\n  @@index([agente])\n  @@map(\"culturas_microbiologicas\")\n}\n\nenum EstadoSurto {\n  activo\n  controlado\n  encerrado\n}\n\nmodel SurtoIACS {\n  id             String      @id @default(uuid())\n  agente         String\n  servico        String\n  dataInicio     DateTime\n  dataFim        DateTime?\n  estado         EstadoSurto @default(activo)\n  numCasos       Int         @default(1)\n  medidas        Json?\n  observacoes    String?\n  registadoPorId String\n  registadoPor   Utilizador  @relation(fields: [registadoPorId], references: [id], onDelete: Cascade)\n  criadoEm       DateTime    @default(now())\n\n  @@index([estado])\n  @@index([agente])\n  @@map(\"surtos_iacs\")\n}\n\n// ─── Conformidade / RGPD Checklist ───────────────────────────────────────────\n\nmodel ConformidadeChecklistItem {\n  id              String      @id @default(uuid())\n  itemKey         String      @unique\n  estado          String      @default(\"verificar\") // 'conforme' | 'verificar' | 'nao_conforme'\n  atualizadoEm    DateTime    @updatedAt\n  atualizadoPorId String?\n  atualizadoPor   Utilizador? @relation(\"ChecklistAtualizador\", fields: [atualizadoPorId], references: [id], onDelete: SetNull)\n\n  @@map(\"conformidade_checklist\")\n}\n\n// ─── Session 49: Sinalizar como Preocupante ───────────────────────────────────\n\nmodel SinalizacaoPreocupante {\n  id             String    @id @default(uuid())\n  doenteId       String\n  criadaPorId    String\n  criadaEm       DateTime  @default(now())\n  resolvida      Boolean   @default(false)\n  resolvidaEm    DateTime?\n  resolvidaPorId String?\n  motivo         String    @db.VarChar(500)\n  nivelUrgencia  String    @default(\"normal\") // 'normal' | 'urgente'\n\n  doente       Doente      @relation(fields: [doenteId], references: [id], onDelete: Cascade)\n  criadaPor    Utilizador  @relation(\"SinalizacoesCriadas\", fields: [criadaPorId], references: [id], onDelete: Cascade)\n  resolvidaPor Utilizador? @relation(\"SinalizacoesResolvidas\", fields: [resolvidaPorId], references: [id], onDelete: SetNull)\n\n  @@index([doenteId, resolvida])\n  @@map(\"sinalizacoes_preocupante\")\n}\n\n// ─── Session 49: Sepsis Sentinel ─────────────────────────────────────────────\n\nmodel AlertaSepsis {\n  id          String    @id @default(uuid())\n  doenteId    String\n  criadoEm    DateTime  @default(now())\n  criterio    String // 'qsofa' | 'sirs'\n  score       Int\n  resolvido   Boolean   @default(false)\n  resolvidoEm DateTime?\n\n  hemoculturasColhidas  Boolean   @default(false)\n  hemoculturasEm        DateTime?\n  antibioticosIniciados Boolean   @default(false)\n  antibioticosEm        DateTime?\n  lactatoMedido         Boolean   @default(false)\n  lactatoEm             DateTime?\n  fluidoterapiaIniciada Boolean   @default(false)\n  fluidoterapiaEm       DateTime?\n\n  doente Doente @relation(fields: [doenteId], references: [id], onDelete: Cascade)\n\n  @@index([doenteId, resolvido])\n  @@map(\"alertas_sepsis\")\n}\n\n// ─── Session 49: Baselines Individuais ───────────────────────────────────────\n\nmodel BaselineDoente {\n  id          String   @id @default(uuid())\n  doenteId    String   @unique\n  calculadaEm DateTime @default(now())\n  nRegistos   Int\n\n  fcMedia            Float?\n  fcSd               Float?\n  pasSistolicaMedia  Float?\n  pasSistolicaSd     Float?\n  pasDiastolicaMedia Float?\n  pasDiastolicaSd    Float?\n  tempMedia          Float?\n  tempSd             Float?\n  spo2Media          Float?\n  spo2Sd             Float?\n  frMedia            Float?\n  frSd               Float?\n\n  doente Doente @relation(fields: [doenteId], references: [id], onDelete: Cascade)\n\n  @@map(\"baselines_doente\")\n}\n\n// ─── Session 49: Planeamento de Alta ─────────────────────────────────────────\n\nmodel PlanoAlta {\n  id          String    @id @default(uuid())\n  doenteId    String    @unique\n  criadoEm    DateTime  @default(now())\n  dataAlvoDia DateTime?\n\n  afebrилApenas24h   Boolean @default(false)\n  mobilidadeAdequada   Boolean @default(false)\n  alimentacaoOral      Boolean @default(false)\n  doresControladas     Boolean @default(false)\n  familiaInformada     Boolean @default(false)\n  transporteAssegurado Boolean @default(false)\n  medicacaoPreparada   Boolean @default(false)\n  consultaSegAlt       Boolean @default(false)\n  notas                String? @db.VarChar(1000)\n\n  doente Doente @relation(fields: [doenteId], references: [id], onDelete: Cascade)\n\n  @@map(\"planos_alta\")\n}\n\n// ─── Session 49: Farmácia / Reconciliação ────────────────────────────────────\n\nmodel ReconciliacaoMedicacao {\n  id            String    @id @default(uuid())\n  doenteId      String\n  criadoPorId   String\n  criadaEm      DateTime  @default(now())\n  medicacaoCasa String    @db.Text\n  discrepancias String    @db.Text\n  aprovadaEm    DateTime?\n  aprovadaPorId String?\n\n  doente      Doente      @relation(fields: [doenteId], references: [id], onDelete: Cascade)\n  criadoPor   Utilizador  @relation(\"ReconciliacoesCriadas\", fields: [criadoPorId], references: [id], onDelete: Cascade)\n  aprovadaPor Utilizador? @relation(\"ReconciliacoesAprovadas\", fields: [aprovadaPorId], references: [id], onDelete: SetNull)\n\n  @@index([doenteId])\n  @@map(\"reconciliacoes_medicacao\")\n}\n\n// ─── Session 49: Relatório de Passagem de Turno ───────────────────────────────\n\nmodel RelatorioPassagemTurno {\n  id              String    @id @default(uuid())\n  criadaEm        DateTime  @default(now())\n  turno           String // 'manha' | 'tarde' | 'noite'\n  servico         String\n  criadaPorId     String\n  confirmadaEm    DateTime?\n  confirmadaPorId String?\n  rascunho        String    @db.Text\n  conteudo        String    @db.Text\n\n  criadaPor     Utilizador  @relation(\"RelatorioPassagemCriado\", fields: [criadaPorId], references: [id], onDelete: Cascade)\n  confirmadaPor Utilizador? @relation(\"RelatorioPassagemConfirmado\", fields: [confirmadaPorId], references: [id], onDelete: SetNull)\n\n  @@index([servico, criadaEm])\n  @@map(\"relatorios_passagem_turno\")\n}\n\n// ─── Session 49: Portal de Família ───────────────────────────────────────────\n\nmodel AcessoFamiliar {\n  id                String   @id @default(uuid())\n  doenteId          String\n  criadoPorId       String\n  criadoEm          DateTime @default(now())\n  nomeContacto      String\n  email             String\n  accessToken       String   @unique @default(cuid())\n  accessTokenExpiry DateTime\n  ativo             Boolean  @default(true)\n\n  doente    Doente     @relation(fields: [doenteId], references: [id], onDelete: Cascade)\n  criadoPor Utilizador @relation(\"AcessoFamiliarCriado\", fields: [criadoPorId], references: [id], onDelete: Cascade)\n\n  @@index([doenteId, ativo])\n  @@index([accessToken])\n  @@map(\"acessos_familiares\")\n}\n\n// ─── Session 49: Dispositivos FHIR ───────────────────────────────────────────\n\nmodel DispositivoFhir {\n  id         String    @id @default(uuid())\n  nome       String\n  tipo       String // 'monitor_vitais' | 'ventilador' | 'bomba_infusao'\n  apiKey     String    @unique @default(cuid())\n  doenteId   String?\n  ativo      Boolean   @default(true)\n  ultimoPing DateTime?\n  criadoEm   DateTime  @default(now())\n\n  @@index([ativo])\n  @@map(\"dispositivos_fhir\")\n}\n\n// ─── Session 53: Dossier Universal + AI Feedback ─────────────────────────────\n\nmodel SistemaExternoSaude {\n  id                  String    @id @default(uuid())\n  nome                String\n  tipo                String // 'fhir_r4' | 'dicom_wado' | 'hl7_v2' | 'upload_manual'\n  endpoint            String?\n  authTipo            String    @default(\"api_key\") // 'api_key' | 'oauth2' | 'none'\n  authConfig          String? // JSON encriptado com credenciais\n  ativo               Boolean   @default(true)\n  ultimaSincronizacao DateTime?\n  criadoEm            DateTime  @default(now())\n\n  documentos DocumentoSaude[]\n\n  @@index([ativo, tipo])\n  @@map(\"sistemas_externos_saude\")\n}\n\nmodel IdentificadorExterno {\n  id       String @id @default(uuid())\n  doenteId String\n  sistema  String // nome/id do sistema\n  valorId  String // ID do doente nesse sistema\n  tipo     String // 'sns' | 'nif' | 'hospital_id' | 'fhir_patient_id'\n\n  doente Doente @relation(fields: [doenteId], references: [id], onDelete: Cascade)\n\n  @@unique([doenteId, sistema, tipo])\n  @@index([doenteId])\n  @@map(\"identificadores_externos\")\n}\n\nmodel DocumentoSaude {\n  id              String    @id @default(uuid())\n  doenteId        String\n  tipo            String // 'rx'|'tc'|'rmn'|'eco'|'ecg'|'lab'|'alta'|'prescricao'|'vacinacao'|'patologia'|'outro'\n  titulo          String\n  descricao       String?\n  dataDocumento   DateTime\n  origem          String // \"Hospital Santa Maria\", \"Synlab\", \"Upload manual\"\n  sistemaOrigemId String?\n  formato         String // 'pdf'|'dicom'|'jpg'|'png'|'hl7'|'fhir_json'\n  storageKey      String? // S3/MinIO object key (null se referência externa)\n  urlExterna      String? // Link PACS ou sistema origem\n  mimeType        String\n  tamanhoBytes    Int?\n  fhirResourceId  String? // ID do recurso FHIR (para upsert)\n  modalidadeDicom String? // 'CR'|'CT'|'MR'|'US'|'DX'|'NM'\n  verificado      Boolean   @default(false)\n  registadoPorId  String?\n  assinadoEm      DateTime?\n  assinadoPorId   String?\n  hashSHA256      String?\n  criadoEm        DateTime  @default(now())\n\n  doente        Doente               @relation(fields: [doenteId], references: [id], onDelete: Cascade)\n  sistemaOrigem SistemaExternoSaude? @relation(fields: [sistemaOrigemId], references: [id], onDelete: SetNull)\n  registadoPor  Utilizador?          @relation(\"DocumentosSaudeRegisto\", fields: [registadoPorId], references: [id], onDelete: SetNull)\n  assinadoPor   Utilizador?          @relation(\"DocumentoSaudeAssinatura\", fields: [assinadoPorId], references: [id], onDelete: SetNull)\n\n  @@index([doenteId, tipo])\n  @@index([doenteId, dataDocumento])\n  @@index([fhirResourceId])\n  @@map(\"documentos_saude\")\n}\n\nmodel AiDecisao {\n  id             String   @id @default(uuid())\n  tipo           String // 'analise'|'triagem'|'protocolo'|'turno'|'los'\n  payload        Json\n  aceite         Boolean?\n  overrideMotivo String?\n  doenteId       String?\n  utilizadorId   String\n  inputPayload   Json?\n  criadoEm       DateTime @default(now())\n\n  utilizador Utilizador @relation(\"AiDecisoes\", fields: [utilizadorId], references: [id], onDelete: Cascade)\n\n  @@index([doenteId, criadoEm])\n  @@index([tipo, criadoEm])\n  @@map(\"ai_decisoes\")\n}\n\nmodel AiMetrica {\n  id           String   @id @default(uuid())\n  feature      String\n  modelo       String\n  latencyMs    Int\n  inputTokens  Int\n  outputTokens Int\n  success      Boolean\n  erro         String?\n  criadoEm     DateTime @default(now())\n\n  @@index([feature, criadoEm])\n  @@map(\"ai_metricas\")\n}\n\nmodel OutcomeClinico {\n  id                     String   @id @default(uuid())\n  doenteId               String\n  tipo                   String // 'readmissao_30d' | 'obito_intra' | 'complicacao' | 'melhoria'\n  descricao              String?\n  dataOcorrido           DateTime\n  relacionadoAiDecisaoId String?\n  registadoPorId         String\n  criadoEm               DateTime @default(now())\n\n  doente       Doente     @relation(fields: [doenteId], references: [id], onDelete: Cascade)\n  registadoPor Utilizador @relation(\"OutcomesRegistados\", fields: [registadoPorId], references: [id])\n\n  @@index([doenteId, tipo])\n  @@index([tipo, criadoEm])\n  @@map(\"outcomes_clinicos\")\n}\n\n// ─── Session 52: Resultados Analíticos (Lab) ─────────────────────────────────\n\nmodel ResultadoAnalise {\n  id             String   @id @default(uuid())\n  doenteId       String\n  parametro      String // 'Hemoglobina', 'Leucócitos', 'PCR', etc.\n  valor          Float\n  unidade        String // 'g/dL', '10^9/L', 'mg/L', etc.\n  refMin         Float? // limite inferior de referência\n  refMax         Float? // limite superior de referência\n  alterado       Boolean  @default(false) // fora do intervalo de referência\n  critico        Boolean  @default(false) // valor crítico / alarmante\n  painel         String? // 'hemograma', 'bioquimica', 'coagulacao', 'microbiologia'\n  observacoes    String?\n  registadoEm    DateTime @default(now())\n  registadoPorId String?\n\n  doente       Doente      @relation(fields: [doenteId], references: [id], onDelete: Cascade)\n  registadoPor Utilizador? @relation(\"ResultadosAnaliseRegisto\", fields: [registadoPorId], references: [id], onDelete: SetNull)\n\n  @@index([doenteId, registadoEm])\n  @@index([critico])\n  @@map(\"resultados_analise\")\n}\n\n// ─── Fotografia Clínica ───────────────────────────────────────────────────────\n\nmodel FotoFerida {\n  id          String   @id @default(uuid())\n  avaliacaoId String\n  storageKey  String\n  mimeType    String // 'image/jpeg' | 'image/png'\n  ordem       Int      @default(0)\n  criadaEm    DateTime @default(now())\n  criadaPorId String\n  analiseIA   Json? // { estadio, sinaisInfecao, tecidoLeito, recomendacao, confianca, analisadaEm }\n\n  avaliacao AvaliacaoFerida @relation(fields: [avaliacaoId], references: [id], onDelete: Cascade)\n  criadaPor Utilizador      @relation(\"FotosFeridasCriadas\", fields: [criadaPorId], references: [id], onDelete: Cascade)\n\n  @@index([avaliacaoId])\n  @@map(\"fotos_feridas\")\n}\n\n// ─── Guidelines Clínicas (RAG) ────────────────────────────────────────────────\n\nmodel GuidelineClinica {\n  id            String   @id @default(uuid())\n  titulo        String\n  categoria     String // 'sepsis'|'antibioterapia'|'feridas'|'isolamento'|'dor'|'medicacao'|'geral'\n  conteudo      String   @db.Text\n  fonte         String // \"DGS 2024\", \"Protocolo Hospital\", \"NICE 2023\"\n  versao        String?\n  ativo         Boolean  @default(true)\n  criadoEm      DateTime @default(now())\n  embeddingJson String?  @db.Text\n\n  @@index([categoria])\n  @@map(\"guidelines_clinicas\")\n}\n\n// ─── Cohort Analysis / Population Health ─────────────────────────────────────\n\nmodel CohortDefinition {\n  id          String   @id @default(uuid())\n  nome        String\n  filtros     Json // { diagnostico?, idadeMin?, idadeMax?, servico?, icd10Code? }\n  criadoPorId String\n  criadoEm    DateTime @default(now())\n\n  criadoPor Utilizador @relation(\"CohortsCriadas\", fields: [criadoPorId], references: [id])\n\n  @@index([criadoPorId])\n  @@map(\"cohort_definitions\")\n}\n\n// ─── Patient-Reported Outcomes (PROs) ────────────────────────────────────────\n\nmodel TemplatePRO {\n  id       String   @id @default(uuid())\n  nome     String\n  campos   Json // [{ id, label, tipo:'scale'|'bool'|'text', min?, max? }]\n  ativo    Boolean  @default(true)\n  criadoEm DateTime @default(now())\n\n  registos RegistoPRO[]\n\n  @@map(\"templates_pro\")\n}\n\nmodel RegistoPRO {\n  id         String   @id @default(uuid())\n  doenteId   String\n  templateId String\n  respostas  Json // { campoId: valor }\n  criadoEm   DateTime @default(now())\n\n  doente   Doente      @relation(fields: [doenteId], references: [id], onDelete: Cascade)\n  template TemplatePRO @relation(fields: [templateId], references: [id])\n\n  @@index([doenteId, criadoEm])\n  @@map(\"registos_pro\")\n}\n\n// ─── Portal do Doente ─────────────────────────────────────────────────────────\n\nmodel PortalDoente {\n  id           String   @id @default(uuid())\n  doenteId     String   @unique\n  email        String   @unique\n  passwordHash String\n  ativo        Boolean  @default(true)\n  criadoPorId  String\n  criadoEm     DateTime @default(now())\n\n  doente    Doente     @relation(fields: [doenteId], references: [id], onDelete: Cascade)\n  criadoPor Utilizador @relation(\"PortalDoentesCriados\", fields: [criadoPorId], references: [id], onDelete: Cascade)\n\n  @@map(\"portal_doentes\")\n}\n\n// ─── HL7 v2 ──────────────────────────────────────────────────────────────────\n\nmodel Hl7Mensagem {\n  id          String   @id @default(uuid())\n  tipo        String // \"ORU^R01\", \"ADT^A01\", \"ADT^A03\", etc.\n  remetente   String? // MSH.3 sending application\n  conteudoRaw String   @db.Text\n  processado  Boolean  @default(false)\n  erroMsg     String?\n  criadoEm    DateTime @default(now())\n\n  @@index([tipo, processado])\n  @@map(\"hl7_mensagens\")\n}\n\n// ─── Dashboard Personalizável ─────────────────────────────────────────────────\n\nmodel DashboardConfig {\n  id           String   @id @default(uuid())\n  userId       String   @unique\n  widgets      Json // [{ id: string, x: number, y: number, w: number, h: number, visible: boolean }]\n  atualizadoEm DateTime @updatedAt\n  criadoEm     DateTime @default(now())\n\n  utilizador Utilizador @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@map(\"dashboard_configs\")\n}\n\n// ─── Follow-Up Pós-Alta ───────────────────────────────────────────────────────\n\nmodel FollowUpAgendado {\n  id            String     @id @default(uuid())\n  doenteId      String\n  doente        Doente     @relation(fields: [doenteId], references: [id], onDelete: Cascade)\n  tipo          String // '7_dias' | '30_dias' | 'consulta_especialidade'\n  dataAgendada  DateTime\n  especialidade String?\n  responsavelId String\n  responsavel   Utilizador @relation(fields: [responsavelId], references: [id], onDelete: Cascade)\n  concluido     Boolean    @default(false)\n  observacoes   String?    @db.Text\n  criadoEm      DateTime   @default(now())\n\n  @@index([responsavelId, concluido])\n  @@index([doenteId])\n  @@map(\"followup_agendados\")\n}\n\n// ─── Webhooks / Integration API ───────────────────────────────────────────────\n\nmodel Webhook {\n  id          String   @id @default(uuid())\n  url         String\n  secret      String\n  eventos     String[]\n  ativo       Boolean  @default(true)\n  criadoPorId String\n  criadoEm    DateTime @default(now())\n\n  criadoPor Utilizador @relation(\"WebhooksCriados\", fields: [criadoPorId], references: [id])\n\n  @@index([criadoPorId])\n  @@map(\"webhooks\")\n}\n\n// ─── WebAuthn / FIDO2 passkeys ───────────────────────────────────────────────\n\nmodel WebAuthnCredential {\n  id           String     @id @default(uuid())\n  credentialId String     @unique\n  publicKey    Bytes\n  counter      BigInt     @default(0)\n  deviceType   String     @default(\"singleDevice\") // 'singleDevice' | 'multiDevice'\n  backedUp     Boolean    @default(false)\n  transports   String[] // ['internal', 'usb', 'ble', 'nfc', 'hybrid', 'cable']\n  nome         String     @default(\"Passkey\") // nome dado pelo utilizador\n  utilizadorId String\n  utilizador   Utilizador @relation(fields: [utilizadorId], references: [id], onDelete: Cascade)\n  criadoEm     DateTime   @default(now())\n  ultimoUsoEm  DateTime?\n\n  @@index([utilizadorId])\n  @@map(\"webauthn_credentials\")\n}\n\n// ─── AI Prompt Insights (feedback analysis) ──────────────────────────────────\n\nmodel AiPromptInsight {\n  id           String   @id @default(uuid())\n  semana       DateTime @db.Date\n  tipo         String\n  taxaRejeicao Float\n  padroes      String   @db.Text\n  sugestao     String   @db.Text\n  criadoEm     DateTime @default(now())\n\n  @@index([semana])\n  @@map(\"ai_prompt_insights\")\n}\n\n// ─── AI Staffing Previsão ────────────────────────────────────────────────────\n\nmodel AiStaffingPrevisao {\n  id                 String   @id @default(uuid())\n  data               DateTime @db.Date\n  turno              String // 'manha' | 'tarde' | 'noite'\n  servicoId          String?\n  pessoalAtual       Int?\n  pessoalRecomendado Int\n  motivo             String   @db.Text\n  confianca          String // 'alta' | 'media' | 'baixa'\n  criadoEm           DateTime @default(now())\n\n  @@index([data])\n  @@map(\"ai_staffing_previsoes\")\n}\n\n// ─── Staff Wellbeing ─────────────────────────────────────────────────────────\n\nmodel WellbeingSurvey {\n  id           String   @id @default(uuid())\n  utilizadorId String? // null = anónimo\n  respostas    Json // { q1: 1-5, q2: 1-5, ... }\n  scoreGlobal  Int // 1-100\n  semana       DateTime @db.Date\n  criadoEm     DateTime @default(now())\n\n  @@index([semana])\n  @@map(\"wellbeing_surveys\")\n}\n\n// ─── Inter-hospital Transfer ──────────────────────────────────────────────────\n\nmodel TransferenciaExterna {\n  id              String    @id @default(uuid())\n  doenteId        String\n  hospitalDestino String\n  servicoDestino  String\n  motivoTransfer  String    @db.Text\n  estado          String    @default(\"pendente\")\n  solicitadoPorId String\n  aceitoPorId     String?\n  notas           String?   @db.Text\n  documentos      Json?\n  criadoEm        DateTime  @default(now())\n  concluidaEm     DateTime?\n\n  doente        Doente      @relation(fields: [doenteId], references: [id])\n  solicitadoPor Utilizador  @relation(\"TransferenciasSolicitadas\", fields: [solicitadoPorId], references: [id])\n  aceitoPor     Utilizador? @relation(\"TransferenciasAceites\", fields: [aceitoPorId], references: [id])\n\n  @@index([doenteId])\n  @@index([estado])\n  @@map(\"transferencias_externas\")\n}\n\n// ─── Clinical Rules Engine ────────────────────────────────────────────────────\n\nmodel RegraClinica {\n  id          String   @id @default(uuid())\n  nome        String\n  condicao    Json // { parametro:'spo2', operador:'<', valor:90 }\n  acoes       Json // [{ tipo:'notificar', role:'medico' }]\n  ativa       Boolean  @default(true)\n  servicoId   String?\n  criadoPorId String\n  criadoEm    DateTime @default(now())\n\n  criadoPor Utilizador @relation(\"RegrasCliniasCriadas\", fields: [criadoPorId], references: [id])\n\n  @@index([ativa])\n  @@map(\"regras_clinicas\")\n}\n\n// ─── SSO Providers ────────────────────────────────────────────────────────────\n\nmodel SsoProvider {\n  id       String   @id @default(uuid())\n  tipo     String // 'saml' | 'oidc'\n  nome     String\n  config   Json // { entryPoint, cert, issuer, clientId, clientSecret, redirectUri, ... }\n  ativo    Boolean  @default(true)\n  criadoEm DateTime @default(now())\n\n  @@map(\"sso_providers\")\n}\n\n// ─── Maternidade / Obstetrícia ──────────────────────────────────────────────\n\nmodel Gravidez {\n  id                    String              @id @default(uuid())\n  doenteId              String\n  doente                Doente              @relation(fields: [doenteId], references: [id], onDelete: Cascade)\n  dataUltimaMenstruacao DateTime? // DUM\n  dataPrevistaParto     DateTime? // DPP (calculada da DUM se não indicada)\n  gravida               Int? // G — nº de gestações\n  para                  Int? // P — nº de partos\n  grupoSanguineo        String?\n  fatoresRisco          String?\n  estado                String              @default(\"ativa\") // ativa | concluida | interrompida\n  criadoPorId           String\n  criadoEm              DateTime            @default(now())\n  registosPartograma    RegistoPartograma[]\n  parto                 Parto?\n\n  @@index([doenteId, estado])\n  @@map(\"gravidezes\")\n}\n\nmodel RegistoPartograma {\n  id                  String   @id @default(uuid())\n  gravidezId          String\n  gravidez            Gravidez @relation(fields: [gravidezId], references: [id], onDelete: Cascade)\n  momento             DateTime @default(now())\n  dilatacaoCm         Int? // 0-10\n  fcFetal             Int? // bpm\n  contracoes10min     Int? // contrações por 10 min\n  descidaApresentacao Int? // estação -3..+3\n  notas               String?\n  registadoPorId      String\n\n  @@index([gravidezId, momento])\n  @@map(\"registos_partograma\")\n}\n\nmodel Parto {\n  id             String   @id @default(uuid())\n  gravidezId     String   @unique\n  gravidez       Gravidez @relation(fields: [gravidezId], references: [id], onDelete: Cascade)\n  dataHora       DateTime @default(now())\n  tipo           String // eutocico | cesariana | ventosa | forceps\n  complicacoes   String?\n  apgar1         Int? // 0-10\n  apgar5         Int? // 0-10\n  pesoRN         Float? // peso do recém-nascido (kg)\n  sexoRN         String?\n  registadoPorId String\n\n  @@map(\"partos\")\n}\n\n// ─── Oncologia / Quimioterapia ──────────────────────────────────────────────\n\nmodel PlanoQuimioterapia {\n  id                   String               @id @default(uuid())\n  doenteId             String\n  doente               Doente               @relation(fields: [doenteId], references: [id], onDelete: Cascade)\n  protocoloNome        String\n  ciclosPrevistos      Int\n  intervaloDias        Int                  @default(21)\n  alturaCm             Float?\n  pesoKg               Float?\n  superficieCorporalM2 Float? // BSA (Mosteller)\n  farmacos             Json // [{ nome, mgPorM2, doseMaximaMg? }]\n  estado               String               @default(\"ativo\") // ativo | concluido | suspenso\n  criadoPorId          String\n  criadoEm             DateTime             @default(now())\n  ciclos               CicloQuimioterapia[]\n\n  @@index([doenteId, estado])\n  @@map(\"planos_quimioterapia\")\n}\n\nmodel CicloQuimioterapia {\n  id                String             @id @default(uuid())\n  planoId           String\n  plano             PlanoQuimioterapia @relation(fields: [planoId], references: [id], onDelete: Cascade)\n  numero            Int\n  dataPrevista      DateTime?\n  dataAdministracao DateTime?\n  estado            String             @default(\"agendado\") // agendado | administrado | adiado | cancelado\n  toxicidadeGrau    Int? // CTCAE 0-4\n  notas             String?\n  registadoPorId    String?\n\n  @@index([planoId, numero])\n  @@map(\"ciclos_quimioterapia\")\n}\n\n// ─── Diálise / Nefrologia ───────────────────────────────────────────────────\n\nmodel SessaoDialise {\n  id               String   @id @default(uuid())\n  doenteId         String\n  doente           Doente   @relation(fields: [doenteId], references: [id], onDelete: Cascade)\n  data             DateTime @default(now())\n  modalidade       String // hemodialise | dialise_peritoneal\n  duracaoMin       Int?\n  pesoSecoKg       Float? // peso seco alvo\n  pesoPreKg        Float?\n  pesoPosKg        Float?\n  ultrafiltracaoMl Int? // volume removido\n  fluxoSangueMlMin Int?\n  acessoVascular   String? // fistula | cateter | protese\n  paSistolicaPre   Int?\n  paSistolicaPos   Int?\n  complicacoes     String?\n  notas            String?\n  registadoPorId   String\n\n  @@index([doenteId, data])\n  @@map(\"sessoes_dialise\")\n}\n"
}

